window.YC_MORE_QBANKS=window.YC_MORE_QBANKS||[];window.YC_MORE_QBANKS.push([{"id":"zz-30001","module":"zhengzhi","prompt":"马克思主义哲学认为，物质的唯一特性是","options":["广延性","客观实在性","运动性","可知性"],"answer":1,"explanation":"物质的唯一特性是客观实在性，它是不依赖于人的意识而存在、又能为人的意识所反映的。运动是物质的根本属性和存在方式，广延性只是物质的物理属性之一。故本题选B。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30002","module":"zhengzhi","prompt":"“人不能两次踏进同一条河流”，这一命题说明","options":["意识随物质而变化","运动是绝对的，静止是相对的","物质是运动的承担者","静止是运动的特殊状态"],"answer":1,"explanation":"河流的水不断流动更新，人第二次踏入时已非原来的水流，说明事物处于绝对运动之中；同时承认河流在一段时期内仍是“这条河”，又隐含相对静止的存在。该命题直接体现运动绝对性与静止相对性的统一。故本题选B。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30003","module":"zhengzhi","prompt":"“天下之势不盛则衰，天下之治不进则退。”这句话蕴含的哲学道理是","options":["主要矛盾决定事物的发展","矛盾双方在一定条件下相互转化","量变必然引起质变","意识对物质具有反作用"],"answer":1,"explanation":"“盛”与“衰”、“进”与“退”是矛盾的双方，在不盛、不进这样的条件下会向对立面转化，体现了矛盾双方在一定条件下相互转化的辩证法原理。故本题选B。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30004","module":"zhengzhi","prompt":"下列选项中，体现“整体与部分辩证关系”的是","options":["近朱者赤，近墨者黑","牵一发而动全身","千里之堤，溃于蚁穴","塞翁失马，焉知非福"],"answer":1,"explanation":"“牵一发而动全身”指部分的变化会引起整体的改变，体现部分影响整体、关键部分甚至对整体起决定作用的原理。“塞翁失马”体现矛盾转化，“溃于蚁穴”体现量变到质变，“近朱者赤”体现外因影响。故本题选B。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30005","module":"zhengzhi","prompt":"“离离原上草，一岁一枯荣。野火烧不尽，春风吹又生。”其中“野火烧不尽”体现的哲理是","options":["矛盾是事物发展的源泉","事物发展是前进性与曲折性的统一","内因是事物发展的根据","新事物必然战胜旧事物"],"answer":3,"explanation":"草作为新生事物具有旺盛的生命力，野火一时的摧残（旧事物、暂时曲折）无法从根本上消灭它，春风一吹又重新生长，说明代表事物发展方向的新事物是不可战胜的。故本题选D。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30006","module":"zhengzhi","prompt":"“巧妇难为无米之炊”体现的哲学道理是","options":["必然性通过偶然性表现","意识依赖于物质","实践是认识的来源","矛盾的普遍性"],"answer":1,"explanation":"再能干的“巧妇”（主观能动性）也不能脱离“米”（客观物质条件）做饭，说明发挥主观能动性必须以尊重客观条件、依赖物质基础为前提，即意识依赖于物质。故本题选B。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30007","module":"zhengzhi","prompt":"“士别三日，当刮目相待。”这句古语蕴含的哲理是","options":["要用发展的眼光看问题","要抓住矛盾的主要方面","要坚持具体问题具体分析","要用一分为二的观点看问题"],"answer":0,"explanation":"吕蒙读书长进后鲁肃感叹不能再用老眼光看他，说明人和事物是变化发展的，认识也必须随对象的变化而更新，即用发展的眼光看问题。故本题选A。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30008","module":"zhengzhi","prompt":"下列关于实践与认识关系的表述，正确的是","options":["正确的认识对实践没有影响","认识是实践的目的和归宿","认识可以先于实践而产生","实践是认识的来源和发展动力"],"answer":3,"explanation":"实践是认识的来源、发展动力、检验标准和最终目的，B项把目的说成认识、A项否认科学理论对实践的指导作用、C项违背认识来源于实践的基本原理。故本题选D。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30009","module":"zhengzhi","prompt":"“操千曲而后晓声，观千剑而后识器。”这句话强调","options":["意识的能动作用","矛盾的普遍性","质的稳定性","实践出真知"],"answer":3,"explanation":"弹过千支曲子才懂音乐，看过千把剑才识宝剑，说明只有通过反复实践才能获得正确认识，实践是认识的来源。故本题选D。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30010","module":"zhengzhi","prompt":"真理最基本的属性是","options":["相对性","条件性","客观性","绝对性"],"answer":2,"explanation":"真理是人们对客观事物及其规律的正确反映，其内容是客观的，检验标准（实践）也是客观的，客观性是真理最基本的属性。绝对性和相对性是真理的两种属性，但不是“最基本”属性。故本题选C。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30011","module":"zhengzhi","prompt":"“不入虎穴，焉得虎子”与“秀才不出门，全知天下事”分别强调","options":["原因与结果","感性认识与理性认识","现象与本质","直接经验与间接经验"],"answer":3,"explanation":"“入虎穴得虎子”强调亲身实践获得直接经验；“秀才不出门”强调通过书本、他人传授获得间接经验。二者共同说明认识的两个来源渠道，归根到底间接经验也源于他人的实践。故本题选D。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30012","module":"zhengzhi","prompt":"“为者常成，行者常至。”这句话蕴含的方法论是","options":["坚持实践第一的观点","坚持两点论与重点论统一","坚持具体问题具体分析","坚持前途光明与道路曲折统一"],"answer":0,"explanation":"亲自去做才能成功、亲自走才能到达，强调实干和实践的第一性，反对坐而论道。故本题选A。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30013","module":"zhengzhi","prompt":"量变和质变的辩证关系是","options":["量变就是质变，二者没有区别","质变可以脱离量变而发生","量变是质变的必要准备，质变是量变的必然结果","量变只能由质变引起"],"answer":2,"explanation":"事物的发展总是从量变开始，量的积累达到一定程度必然引起质变；质变又为新的量变开辟道路。A项抹杀二者区别，B、D项颠倒关系。故本题选C。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30014","module":"zhengzhi","prompt":"“不积跬步，无以至千里；不积小流，无以成江海。”给我们的启示是","options":["要重视量的积累","要坚持适度原则","要善于抓住主要矛盾","要勇于抓住时机促成质变"],"answer":0,"explanation":"跬步、小流是量的积累，千里、江海是质变，启示我们做事情要脚踏实地、重视量的积累。D项讲质变时机，B项讲防止过度，C项讲矛盾分析。故本题选A。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30015","module":"zhengzhi","prompt":"“过犹不及”体现的哲学道理是","options":["要重视外因作用","要发挥意识的能动性","要坚持适度原则","要促进事物转化"],"answer":2,"explanation":"做过头和做得不够同样不好，说明量变超过一定限度会引起不利的质变，办事情要掌握分寸、坚持适度原则。故本题选C。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30016","module":"zhengzhi","prompt":"辩证否定观认为，否定的实质是","options":["全盘抛弃","简单的重复","扬弃","外力消灭"],"answer":2,"explanation":"辩证的否定是事物自身的否定，既肯定又否定、既克服又保留，其实质是“扬弃”，即抛弃旧事物中消极的因素，保留其积极合理的因素。A项是形而上学的否定观。故本题选C。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30017","module":"zhengzhi","prompt":"对立统一规律在唯物辩证法中的地位是","options":["认识论的基础","辩证法的总特征之一","历史观的基本问题","辩证法的实质和核心"],"answer":3,"explanation":"对立统一规律揭示了事物发展的源泉和动力，是唯物辩证法的实质和核心；联系和发展才是辩证法的总特征。故本题选D。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30018","module":"zhengzhi","prompt":"“和实生物，同则不继。”这一古语的哲学含义是","options":["斗争性推动一切事物发展","量变比质变更重要","差异与对立是事物发展的动力","同一性就是完全一致"],"answer":2,"explanation":"不同的事物相互配合才能生成新事物，完全相同则无法延续发展，说明矛盾的同一性与斗争性相结合才推动事物发展，强调差异、对立在发展中的作用。故本题选C。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30019","module":"zhengzhi","prompt":"“白马非马”这一命题的错误在于","options":["否认了运动的绝对性","割裂了共性与个性、一般与个别的联系","夸大了意识的能动作用","混淆了形式与内容"],"answer":1,"explanation":"“白马”是个别、特殊，“马”是一般、共性，公孙龙把二者割裂并对立起来，否认个别包含一般，属于形而上学的诡辩论。故本题选B。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30020","module":"zhengzhi","prompt":"社会历史观的基本问题是","options":["生产力与生产关系的问题","社会存在与社会意识的关系问题","经济基础与上层建筑的问题","个人与社会的问题"],"answer":1,"explanation":"社会存在与社会意识的关系问题是社会历史观的基本问题，对二者何者为第一性的不同回答，划分出历史唯物主义和历史唯心主义。故本题选B。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30021","module":"zhengzhi","prompt":"“时势造英雄”这一观点强调","options":["英雄人物决定历史方向","意识对社会存在起决定作用","社会存在决定社会意识","个人可以脱离社会历史条件"],"answer":2,"explanation":"英雄人物的出现是特定社会历史条件（时势）的产物，说明社会存在决定社会意识，历史人物的活动受社会历史条件制约。A项夸大个人作用，属历史唯心主义。故本题选C。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30022","module":"zhengzhi","prompt":"在历史创造者问题上，历史唯物主义认为","options":["杰出人物决定历史进程","人民群众是历史的创造者","历史由英雄与群众共同主宰","历史发展纯属偶然"],"answer":1,"explanation":"人民群众是社会物质财富和精神财富的创造者，是社会变革的决定力量，是历史的创造者。故本题选B。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30023","module":"zhengzhi","prompt":"“城门失火，殃及池鱼”体现的哲学道理是","options":["矛盾具有特殊性","事物是变化发展的","认识具有反复性","事物是普遍联系的"],"answer":3,"explanation":"城门失火与池中鱼本不相干，却通过取水灭火这一中介发生联系，说明事物之间存在普遍的、多样的联系，要用联系的观点看问题。故本题选D。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30024","module":"zhengzhi","prompt":"“头痛医头、脚痛医脚”的做法在方法论上的错误是","options":["只见部分不见整体，割裂了事物的普遍联系","否认了矛盾的普遍性","夸大了内因的作用","忽视了意识的能动作用"],"answer":0,"explanation":"孤立地看待局部症状而不从整体把握病因，违背了整体与部分的辩证关系和普遍联系的观点。故本题选A。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30025","module":"zhengzhi","prompt":"“凡事预则立，不预则废。”这句话强调","options":["实践决定认识","物质决定意识","意识活动的目的性和计划性","矛盾的客观性"],"answer":2,"explanation":"事先有谋划、有准备才能成功，说明人的意识活动具有目的性、计划性，发挥正确的意识能动作用有助于实践的成效。故本题选C。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30026","module":"zhengzhi","prompt":"“山重水复疑无路，柳暗花明又一村”蕴含的哲理是","options":["矛盾双方相互依赖","事物发展是前进性与曲折性的统一","外因通过内因起作用","感性认识有待上升为理性认识"],"answer":1,"explanation":"道路看似曲折（疑无路）但前途光明（又一村），说明事物发展的方向是前进的、上升的，道路是曲折的、迂回的。故本题选B。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30027","module":"zhengzhi","prompt":"下列选项中，属于唯物主义观点的是","options":["吾心即宇宙","理在事先","形存则神存，形谢则神灭","心生种种法生，心灭种种法灭"],"answer":2,"explanation":"“形存神存、形谢神灭”认为形体（物质）决定精神（意识），是古代朴素唯物主义的观点；D、A项是主观唯心主义，B项把理念当作本原，属客观唯心主义。故本题选C。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30028","module":"zhengzhi","prompt":"“眼中落的叶子，是心中涌起的秋意”这类“境由心生”的说法，属于","options":["辩证唯物主义","朴素唯物主义","主观唯心主义","客观唯心主义"],"answer":2,"explanation":"把人的主观精神（心、感觉、观念）当作世界的本原，认为事物依赖于人的主观意识，属于主观唯心主义；客观唯心主义则把“理”“上帝”“绝对精神”等客观精神当作本原。故本题选C。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30029","module":"zhengzhi","prompt":"商品是用于交换的劳动产品，其两个基本属性（二因素）是","options":["价值和交换价值","使用价值和交换价值","具体劳动和抽象劳动","使用价值和价值"],"answer":3,"explanation":"商品是用来交换的劳动产品，具有使用价值和价值两个基本因素，价值是商品的本质属性，交换价值是价值的表现形式。故本题选D。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30030","module":"zhengzhi","prompt":"生产商品的劳动具有二重性，即","options":["简单劳动和复杂劳动","必要劳动和剩余劳动","私人劳动和社会劳动","具体劳动和抽象劳动"],"answer":3,"explanation":"具体劳动创造商品的使用价值，抽象劳动形成商品的价值，劳动二重性学说是理解马克思主义政治经济学的枢纽。故本题选D。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30031","module":"zhengzhi","prompt":"货币的五种职能中，最基本的是","options":["流通手段和世界货币","价值尺度和流通手段","贮藏手段和支付手段","支付手段和价值尺度"],"answer":1,"explanation":"价值尺度和流通手段是货币的两种基本职能，货币首先是以这两种职能从商品中分离出来的；贮藏手段、支付手段、世界货币是派生职能。故本题选B。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30032","module":"zhengzhi","prompt":"价值规律的基本内容是","options":["供求关系决定商品的价值","商品的价值量由生产商品的社会必要劳动时间决定，商品交换以价值量为基础实行等价交换","价格围绕价值上下波动","商品的价格由使用价值大小决定"],"answer":1,"explanation":"价值规律的内容是价值量的决定和等价交换原则；价格围绕价值上下波动是价值规律的表现形式而非内容；C项混淆内容与形式，A、D项否认劳动决定价值。故本题选B。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30033","module":"zhengzhi","prompt":"剩余价值是","options":["由雇佣工人的剩余劳动创造、被资本家无偿占有的价值","商品价格高于价值的差额","由全部社会劳动创造的平均利润","机器设备自动创造的新价值"],"answer":0,"explanation":"剩余价值的来源是雇佣工人的剩余劳动，它体现了资本家对工人的剥削关系，这是马克思主义剩余价值学说的核心结论。故本题选A。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30034","module":"zhengzhi","prompt":"资本家提高对工人剥削程度的基本方法概括起来有绝对剩余价值生产和","options":["超额剩余价值生产","简单再生产","扩大再生产","相对剩余价值生产"],"answer":3,"explanation":"绝对剩余价值通过延长工作日获得，相对剩余价值通过提高劳动生产率、缩短必要劳动时间获得，二者是提高剥削程度的两种基本方法。超额剩余价值是相对剩余价值实现的途径之一。故本题选D。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30035","module":"zhengzhi","prompt":"马克思主义哲学区别于一切旧哲学的最显著特征是","options":["实践性","科学性","革命性","阶级性"],"answer":0,"explanation":"马克思把科学的实践观引入哲学，强调哲学不仅要解释世界，更要改变世界，实践性是马克思主义哲学区别于一切旧哲学的最显著、最根本的特征。故本题选A。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30036","module":"zhengzhi","prompt":"“沉舟侧畔千帆过，病树前头万木春”蕴含的哲理是","options":["新事物代替旧事物是事物发展的总趋势","联系具有客观性","矛盾双方相互转化","意识具有能动性"],"answer":0,"explanation":"沉舟、病树比喻旧事物，千帆、万木比喻蓬勃发展的新事物，诗句表达了对新事物必将取代旧事物的发展规律的信心。故本题选A。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30037","module":"zhengzhi","prompt":"“水滴石穿”与“绳锯木断”共同体现的哲理是","options":["量变积累到一定程度会引起质变","认识对实践有反作用","矛盾具有同一性","内因是变化的根据"],"answer":0,"explanation":"水滴、绳锯是持续不断的量变过程，石穿、木断是质变的实现，两句共同强调量变积累引起质变的规律。故本题选A。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30038","module":"zhengzhi","prompt":"“横看成岭侧成峰，远近高低各不同”给我们的方法论启示是","options":["意识决定物质的形态","观察角度影响认识结果，要全面地看问题","真理是主观与客观的统一","运动是物质的固有属性"],"answer":1,"explanation":"同一座庐山，从不同角度看呈现不同景象，说明认识受观察立场、角度的限制，看问题应当多角度、全面化，避免片面性。故本题选B。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30039","module":"zhengzhi","prompt":"“日用而不觉”的传统观念往往能够左右人们的行为，这表明","options":["社会意识与社会存在同步变化","社会意识决定社会存在","落后的社会意识不会阻碍社会发展","社会意识具有相对独立性和历史继承性"],"answer":3,"explanation":"传统观念作为社会意识，会代代相传并影响人们的行为，说明社会意识有相对独立性，其变化与社会存在并不完全同步。C项否认落后意识的阻碍作用，B项颠倒了决定关系。故本题选D。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30040","module":"zhengzhi","prompt":"生产力与生产关系的辩证关系是","options":["生产力随生产关系变化而变化","二者互为决定","生产力决定生产关系，生产关系反作用于生产力","生产关系决定生产力"],"answer":2,"explanation":"生产力是最活跃、最革命的因素，决定生产关系的性质和变革；生产关系对生产力具有反作用，适合则促进、不适合则阻碍。故本题选C。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30041","module":"zhengzhi","prompt":"“兼听则明，偏信则暗”体现的认识论道理是","options":["认识是无限的","真理具有客观性","认识的全面性要求","实践是检验真理的标准"],"answer":2,"explanation":"多方面听取意见才能明辨是非，只听一面之词就会昏暗不明，说明获得正确认识必须全面收集材料、避免以偏概全。故本题选C。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30042","module":"zhengzhi","prompt":"“谋定而后动，知止而有得”主要强调","options":["发挥意识的能动作用要先于行动做好谋划","物质决定意识","一切从实际出发","实践是认识的最终目的"],"answer":0,"explanation":"先谋划周全再行动才能有所收获，强调意识活动的计划性、目的性对实践的指导作用。故本题选A。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30043","module":"zhengzhi","prompt":"“甘瓜苦蒂，天下物无全也”体现的辩证法观点是","options":["量变是质变的前提","事物的矛盾具有普遍性，要一分为二地看问题","现象是本质的外部表现","矛盾的斗争性是绝对的"],"answer":1,"explanation":"瓜甜而蒂苦，天下没有十全十美的事物，说明任何事物都包含对立统一的两个方面，应当坚持两分法、全面看问题。故本题选B。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30044","module":"zhengzhi","prompt":"认识过程的第一次飞跃是指","options":["从相对真理到绝对真理","从理性认识回到实践","从感性认识上升到理性认识","从现象到本质"],"answer":2,"explanation":"认识过程的第一次飞跃是在实践基础上从感性认识上升到理性认识；第二次飞跃是从理性认识回到实践、指导实践，后者意义更为重大。故本题选C。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30045","module":"zhengzhi","prompt":"“刀不磨要生锈，人不学习要落后”强调的哲学依据是","options":["联系的多样性","实践的观点：认识在实践中产生和发展","量变与质变的规律","矛盾的同一性原理"],"answer":1,"explanation":"刀在使用（实践）中保持锋利，人通过学习（实践活动）更新认识，一旦脱离实践和学习的进程，认识就会落后，体现了实践是认识的基础和发展动力。故本题选B。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30046","module":"zhengzhi","prompt":"社会基本矛盾是","options":["无产阶级与资产阶级的矛盾","人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾","计划与市场的矛盾","生产力和生产关系、经济基础和上层建筑的矛盾"],"answer":3,"explanation":"贯穿人类社会发展始终的基本矛盾是生产力与生产关系的矛盾、经济基础与上层建筑的矛盾，它决定社会形态的更替；B项是我国现阶段的主要矛盾，不能与基本矛盾混同。故本题选D。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30047","module":"zhengzhi","prompt":"“耳闻不如目见，目见不如足践”强调","options":["认识可以脱离实践","实践是认识的来源，且亲身实践的认识更深刻","间接经验没有价值","感性认识比理性认识更可靠"],"answer":1,"explanation":"听来的不如亲眼见的，亲眼见的又不如亲自实践的，说明实践出真知，直接经验比间接印象更深刻可靠，但并不否认间接经验的价值。故本题选B。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30048","module":"zhengzhi","prompt":"“先谋后事者昌，先事后谋者亡”中“谋”与“事”的关系，哲学上对应","options":["现象与本质的关系","原因与偶然的关系","认识与实践的关系","形式与内容的关系"],"answer":2,"explanation":"“谋”指计划、认识，“事”指行动、实践，先有正确认识再付诸实践才能成功，对应认识与实践的辩证关系。故本题选C。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30049","module":"zhengzhi","prompt":"偶然性与必然性的辩证关系是","options":["偶然性决定必然性","偶然性与必然性互不相干","必然性是偶然性的总和","必然性通过大量偶然性表现出来，偶然性背后隐藏着必然性"],"answer":3,"explanation":"必然性存在于偶然性之中并通过偶然性开辟道路，偶然性是必然性的表现形式和补充，二者相互依存。故本题选D。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30050","module":"zhengzhi","prompt":"“有无相生，难易相成”体现的辩证法思想是","options":["矛盾的斗争性推动事物发展","矛盾的同一性：矛盾双方相互依存、互为条件","质变是量变的必然结果","联系的客观性"],"answer":1,"explanation":"老子认为“有”与“无”、“难”与“易”相互对立又相互依存，失去一方另一方也不存在，体现了矛盾双方相互依存的同一性原理。故本题选B。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30051","module":"zhengzhi","prompt":"“本”“末”“顺”“置”是中国古代关于轻重主次的思想。“本末倒置”的做法违背了","options":["主次矛盾的辩证关系原理","认识的反复性原理","否定之否定规律","量变质变规律"],"answer":0,"explanation":"本末倒置指把次要的当成主要的、主要的当成次要的，违背了抓主要矛盾、坚持重点论的要求。故本题选A。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30052","module":"zhengzhi","prompt":"“十个指头按跳蚤”比喻什么都想抓反而什么都抓不住，其方法论要求是","options":["集中力量解决主要矛盾","把握联系的多样性","促进矛盾双方转化","坚持矛盾的普遍性"],"answer":0,"explanation":"十个指头同时按十个跳蚤必然一个也按不住，比喻平均用力、不分主次的做法行不通，要求集中主要力量解决主要矛盾。故本题选A。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30053","module":"zhengzhi","prompt":"“布衣 warming 一暖，百姓饥寒难解”这类民本主张，在历史唯物主义视野下对应","options":["人民群众是社会物质财富的创造者","历史是少数精英书写的","社会意识对社会存在毫无作用","英雄人物创造历史"],"answer":0,"explanation":"民生冷暖系于百姓的生产劳动，衣食等物质生活资料由人民群众创造，说明人民群众是社会物质财富的创造者。故本题选A。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30054","module":"zhengzhi","prompt":"商品的价格水平与货币价值之间的关系是","options":["货币价值下降，商品价格下降","货币价值下降，商品价格上涨","商品价格只由供求决定","二者没有关系"],"answer":1,"explanation":"价格是价值的货币表现，商品价格与货币价值成反比：货币自身价值贬值时，表现同一价值量所需货币增多，价格上涨。故本题选B。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30055","module":"zhengzhi","prompt":"“牛无力拖横耙，人无理说横话”，这句俗语强调","options":["说话办事要讲道理，认识要符合客观实际","实践依赖于认识","矛盾双方相互斗争","量变决定质变"],"answer":0,"explanation":"没有道理却说蛮话，正如没有力气的牛拉歪耙，说明人的言论应当以正确认识为前提，尊重客观事实和规律。故本题选A。","__sub":"马原","_shard":"qk-zhengzhi-01"},{"id":"zz-30056","module":"zhengzhi","prompt":"毛泽东思想活的灵魂是","options":["理论联系实际、密切联系群众、批评与自我批评","统一战线、武装斗争、党的建设","解放思想、实事求是、与时俱进","实事求是、群众路线、独立自主"],"answer":3,"explanation":"实事求是、群众路线、独立自主是毛泽东思想活的灵魂的三个基本方面；B项是中国革命三大法宝，A项是党的三大优良作风。故本题选D。","__sub":"毛思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30057","module":"zhengzhi","prompt":"毛泽东思想的精髓是","options":["独立自主","实事求是","武装斗争","群众路线"],"answer":1,"explanation":"实事求是是毛泽东思想的出发点、根本点，是精髓；群众路线和独立自主都是建立在实事求是基础之上的。故本题选B。","__sub":"毛思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30058","module":"zhengzhi","prompt":"中国民主革命“三大法宝”的正确组合是","options":["统一战线、土地革命、党的建设","土地革命、武装斗争、根据地建设","武装斗争、游击战争、政权建设","统一战线、武装斗争、党的建设"],"answer":3,"explanation":"毛泽东在《〈共产党人〉发刊词》中指出，统一战线、武装斗争、党的建设是中国革命克敌制胜的三大法宝。故本题选D。","__sub":"毛思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30059","module":"zhengzhi","prompt":"新民主主义革命区别于旧民主主义革命的根本标志是","options":["革命的动力是农民阶级","无产阶级的领导权","革命的任务是反封建","革命的对象是帝国主义"],"answer":1,"explanation":"领导权问题是区分新旧民主主义革命的根本标志：旧民主主义革命由资产阶级领导，新民主主义革命由无产阶级（通过共产党）领导。故本题选B。","__sub":"毛思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30060","module":"zhengzhi","prompt":"新民主主义革命的性质是","options":["农民阶级的革命","民族解放革命","无产阶级社会主义革命","资产阶级民主革命"],"answer":3,"explanation":"新民主主义革命反帝反封建，就其性质而言仍是资产阶级民主革命，但由于无产阶级领导，它已属于世界无产阶级社会主义革命的一部分，前途是社会主义。故本题选D。","__sub":"毛思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30061","module":"zhengzhi","prompt":"毛泽东提出“农村包围城市、武装夺取政权”革命道路的主要依据是","options":["中国半殖民地半封建的基本国情","共产国际的直接指示","城市工人阶级力量强大","苏联经验的普遍适用性"],"answer":0,"explanation":"中国是半殖民地半封建社会，城市敌人力量强大而农村相对薄弱，农民是革命的主力军，必须走农村包围城市的道路，这是从中国国情出发得出的结论。故本题选A。","__sub":"毛思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30062","module":"zhengzhi","prompt":"标志着毛泽东思想走向成熟、被系统概括为科学理论的会议是","options":["八七会议","党的六届六中全会","党的七大","遵义会议"],"answer":2,"explanation":"1945年党的七大把毛泽东思想确立为党的指导思想并写入党章，刘少奇在会上对毛泽东思想作了系统概括。故本题选C。","__sub":"毛思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30063","module":"zhengzhi","prompt":"群众路线的核心内容是","options":["从群众中来，到群众中去","密切联系群众，关心群众疾苦","批评与自我批评","一切为了群众，一切依靠群众"],"answer":3,"explanation":"“一切为了群众，一切依靠群众”是群众路线的核心内容，回答了“为了谁、依靠谁”的根本问题；“从群众中来，到群众中去”是群众路线的领导方法和工作方法。故本题选D。","__sub":"毛思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30064","module":"zhengzhi","prompt":"1935年1月召开的遵义会议主要解决了","options":["统战策略问题","经济方针问题","土地政策问题","军事路线和组织问题"],"answer":3,"explanation":"遵义会议集中解决当时具有决定意义的军事问题和组织问题，结束了“左”倾教条主义错误在中央的统治，是党的历史上生死攸关的转折点。故本题选D。","__sub":"毛思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30065","module":"zhengzhi","prompt":"毛泽东在《关于正确处理人民内部矛盾的问题》中提出，人民内部矛盾的解决方法是","options":["行政命令强制的方法","剥夺生产资料的方法","专政的方法","民主的方法，即团结—批评—团结"],"answer":3,"explanation":"人民内部矛盾是非对抗性矛盾，只能用民主的、说服教育的方法解决，即“团结—批评—团结”。敌我矛盾才用专政方法。故本题选D。","__sub":"毛思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30066","module":"zhengzhi","prompt":"毛泽东首次提出“一切反动派都是纸老虎”论断的场合，其针对的主要问题是","options":["从战略上藐视敌人、战术上重视敌人","解散根据地","放弃武装斗争","停止土地革命"],"answer":0,"explanation":"“纸老虎”论断要求在战略上藐视敌人、树立必胜信心，同时在战术上重视敌人、善于斗争。故本题选A。","__sub":"毛思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30067","module":"zhengzhi","prompt":"毛泽东《反对本本主义》一文提出的著名论断是","options":["枪杆子里面出政权","没有调查，没有发言权","一切反动派都是纸老虎","星星之火，可以燎原"],"answer":1,"explanation":"《反对本本主义》（1930年）提出“没有调查，没有发言权”，是党的实事求是思想路线形成过程中的重要文献。“枪杆子里面出政权”出自八七会议发言。故本题选B。","__sub":"毛思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30068","module":"zhengzhi","prompt":"新民主主义社会的性质属于","options":["独立的资本主义社会","半殖民地半封建社会","由新民主主义向社会主义过渡的社会形态","完整的社会主义社会"],"answer":2,"explanation":"新民主主义社会是过渡性质的社会，既有社会主义因素又有非社会主义因素，其中社会主义因素起决定作用并不断增长。故本题选C。","__sub":"毛思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30069","module":"zhengzhi","prompt":"1953年党提出的过渡时期总路线的主体是","options":["对资本主义工商业的社会主义改造","对农业的社会主义改造","对手工业的社会主义改造","逐步实现国家的社会主义工业化"],"answer":3,"explanation":"过渡时期总路线简称为“一化三改”，“一化”即社会主义工业化是主体，“三改”是对农业、手工业和资本主义工商业的社会主义改造是两翼。故本题选D。","__sub":"毛思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30070","module":"zhengzhi","prompt":"我国对资本主义工商业社会主义改造采取的创新性方式是","options":["联合经营","无偿没收","和平赎买","公私合营一刀切"],"answer":2,"explanation":"对民族资本主义工商业采取和平赎买的政策，通过国家资本主义形式逐步实现改造，这是国际共产主义运动史上的创举；无偿没收针对官僚资本。故本题选C。","__sub":"毛思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30071","module":"zhengzhi","prompt":"社会主义改造基本完成后，党的八大指出国内的主要矛盾是","options":["生产力和生产关系的矛盾","无产阶级和资产阶级的矛盾","计划经济与市场调节的矛盾","人民对于建立先进的工业国的要求同落后的农业国的现实之间的矛盾"],"answer":3,"explanation":"1956年党的八大正确分析了国内形势和主要矛盾的变化，指出主要矛盾已经是人民对于先进工业国的要求同落后农业国的现实之间的矛盾。故本题选D。","__sub":"毛思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30072","module":"zhengzhi","prompt":"毛泽东思想被正式写入党章并确立为党的指导思想是在","options":["1949年七届二中全会","1935年遵义会议","1945年党的七大","1956年党的八大"],"answer":2,"explanation":"党的七大通过的党章明确规定以毛泽东思想作为党的一切工作的指针，实现了马克思主义中国化的第一次历史性飞跃成果的确立。故本题选C。","__sub":"毛思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30073","module":"zhengzhi","prompt":"“一切从实际出发”与“一切从本本出发”的根本分歧在于","options":["是否承认矛盾的存在","是否承认物质第一性、意识第二性","是否坚持群众观点","是否重视理论学习"],"answer":1,"explanation":"从实际出发坚持物质决定意识，从本本出发把书本、教条当作出发点，二者的根本分歧在哲学上就是物质与意识何者第一性的问题。故本题选B。","__sub":"毛思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30074","module":"zhengzhi","prompt":"《论十大关系》确定的社会主义建设基本方针是","options":["以阶级斗争为纲","调动一切积极因素，为社会主义事业服务","全面照搬苏联模式","优先发展重工业"],"answer":1,"explanation":"《论十大关系》（1956年）提出以苏为鉴、独立探索，基本方针是把国内外一切积极因素调动起来为社会主义事业服务。故本题选B。","__sub":"毛思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30075","module":"zhengzhi","prompt":"“团结—批评—团结”公式适用的矛盾类型是","options":["对抗性矛盾","敌我矛盾","人民内部矛盾","阶级矛盾"],"answer":2,"explanation":"人民内部矛盾属于非对抗性矛盾，采用民主的说服教育方法解决；敌我矛盾是对抗性矛盾，采用专政方法。故本题选C。","__sub":"毛思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30076","module":"zhengzhi","prompt":"毛泽东群众路线工作方法的正确顺序是","options":["先集中再分散","到群众中去，从群众中来","先决策后调研","从群众中来，到群众中去"],"answer":3,"explanation":"将群众分散的意见集中起来化为系统的意见，再到群众中坚持下去并检验修正，循环往复以至无穷，这就是群众路线的基本方法。故本题选D。","__sub":"毛思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30077","module":"zhengzhi","prompt":"近代中国半殖民地半封建社会的主要矛盾是","options":["帝国主义和中华民族的矛盾，封建主义和人民大众的矛盾","地主阶级和资产阶级的矛盾","城市与乡村的矛盾","工人阶级和农民阶级的矛盾"],"answer":0,"explanation":"近代中国社会的主要矛盾是帝国主义与中华民族的矛盾（其中帝国主义与中华民族的矛盾是最主要的矛盾）以及封建主义与人民大众的矛盾。故本题选A。","__sub":"毛思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30078","module":"zhengzhi","prompt":"新民主主义革命的领导阶级是","options":["小资产阶级","无产阶级","民族资产阶级","农民阶级"],"answer":1,"explanation":"新民主主义革命由无产阶级及其政党领导，这是其区别于旧民主主义革命的根本标志。故本题选B。","__sub":"毛思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30079","module":"zhengzhi","prompt":"三湾改编最重要的历史贡献是","options":["建立抗日民族统一战线","确立党对军队的绝对领导，把支部建在连上","确立土地革命路线","决定武装反抗国民党"],"answer":1,"explanation":"1927年三湾改编首次把党支部建在连上，从组织上确立了党对军队的领导，是人民军队建军的重要开端；古田会议进一步确立思想建党、政治建军原则。故本题选B。","__sub":"毛思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30080","module":"zhengzhi","prompt":"“政权是由枪杆子中取得的”这一论断提出于","options":["八七会议","瓦窑堡会议","遵义会议","洛川会议"],"answer":0,"explanation":"1927年八七会议上，毛泽东提出“须知政权是由枪杆子中取得的”，确定了土地革命和武装反抗国民党反动派的总方针。故本题选A。","__sub":"毛思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30081","module":"zhengzhi","prompt":"毛泽东在《实践论》《矛盾论》中着重批判的错误倾向是","options":["冒险主义","教条主义","经验主义","投降主义"],"answer":1,"explanation":"《实践论》《矛盾论》（1937年）从认识论和辩证法的高度批判教条主义（本本主义），为党的实事求是思想路线奠定了理论基础。故本题选B。","__sub":"毛思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30082","module":"zhengzhi","prompt":"抗日民族统一战线政策正式确立的会议是","options":["六届六中全会","瓦窑堡会议","洛川会议","遵义会议"],"answer":1,"explanation":"1935年底瓦窑堡会议确定了建立抗日民族统一战线的策略方针；洛川会议制定《抗日救国十大纲领》，强调全面抗战路线。故本题选B。","__sub":"毛思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30083","module":"zhengzhi","prompt":"党的七届二中全会提出的“两个务必”是指","options":["务必节约粮食，务必勤俭建国","务必发展生产，务必整顿党风","务必统一思想，务必统一行动","务必使同志们继续地保持谦虚、谨慎、不骄、不躁的作风，务必使同志们继续地保持艰苦奋斗的作风"],"answer":3,"explanation":"1949年七届二中全会上毛泽东提出“两个务必”，告诫全党在革命胜利后警惕骄傲自满和贪图享乐，是西柏坡精神的核心内容。故本题选D。","__sub":"毛思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30084","module":"zhengzhi","prompt":"毛泽东思想关于党的建设理论中，特别强调放在首位的建设是","options":["思想建设","制度建设","组织建设","作风建设"],"answer":0,"explanation":"着重从思想上建党，把思想建设放在首位，是中国共产党建设的重要特点和经验，源于党内农民和小资产阶级出身党员占多数的实际。故本题选A。","__sub":"毛思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30085","module":"zhengzhi","prompt":"新中国成立初期开展的“抗美援朝、保家卫国”运动，就毛泽东思想的国际意义而言，体现的是","options":["独立自主原则在对外关系中的运用","统一战线在党内的运用","土地革命路线的延续","群众路线的运用"],"answer":0,"explanation":"抗美援朝体现了新中国不畏强权、独立自主处理对外关系和维护国家安全的立场，是独立自主这一活的灵魂在外交领域的体现。故本题选A。","__sub":"毛思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30086","module":"zhengzhi","prompt":"邓小平理论首要的基本理论问题是","options":["实现什么样的发展、怎样发展","建设什么样的党、怎样建设党","什么是现代化、怎样实现现代化","什么是社会主义、怎样建设社会主义"],"answer":3,"explanation":"邓小平理论围绕“什么是社会主义、怎样建设社会主义”这一首要基本理论问题展开；B项是“三个代表”重要思想的主题，A项是科学发展观的主题。故本题选D。","__sub":"中特","_shard":"qk-zhengzhi-01"},{"id":"zz-30087","module":"zhengzhi","prompt":"邓小平对社会主义本质的概括是","options":["人民当家作主","高度的物质文明和精神文明","解放生产力，发展生产力，消灭剥削，消除两极分化，最终达到共同富裕","公有制为主体，按劳分配为主体"],"answer":2,"explanation":"1992年南方谈话中，邓小平把社会主义本质概括为上述五句话，其中解放和发展生产力是根本任务，共同富裕是最终目标。故本题选C。","__sub":"中特","_shard":"qk-zhengzhi-01"},{"id":"zz-30088","module":"zhengzhi","prompt":"党的基本路线中的“一个中心、两个基本点”是指","options":["以人民为中心，坚持发展、坚持安全","以经济建设为中心，坚持四项基本原则、坚持改革开放","以文化建设为中心，坚持传承、坚持创新","以政治建设为中心，坚持法治、坚持德治"],"answer":1,"explanation":"党的基本路线的核心内容是“一个中心、两个基本点”：以经济建设为中心，坚持四项基本原则，坚持改革开放。故本题选B。","__sub":"中特","_shard":"qk-zhengzhi-01"},{"id":"zz-30089","module":"zhengzhi","prompt":"我国社会主义初级阶段的主要矛盾（1978年后直至2017年）曾是","options":["人民日益增长的物质文化需要同落后的社会生产之间的矛盾","商品供给与需求的矛盾","无产阶级与资产阶级的矛盾","人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾"],"answer":0,"explanation":"1981年党的十一届六中全会将主要矛盾概括为人民日益增长的物质文化需要同落后的社会生产之间的矛盾；2017年十九大转化为D项表述。故本题选A。","__sub":"中特","_shard":"qk-zhengzhi-01"},{"id":"zz-30090","module":"zhengzhi","prompt":"“三步走”发展战略由邓小平提出，其中第二步的目标是","options":["解决人民温饱问题","建成社会主义现代化强国","到20世纪末，人民生活达到小康水平","人均国民生产总值达到中等发达国家水平"],"answer":2,"explanation":"“三步走”：第一步温饱，第二步20世纪末小康，第三步21世纪中叶基本实现现代化。故本题选C。","__sub":"中特","_shard":"qk-zhengzhi-01"},{"id":"zz-30091","module":"zhengzhi","prompt":"“科学技术是第一生产力”这一论断的提出者是","options":["邓小平","周恩来","马克思","毛泽东"],"answer":0,"explanation":"1988年邓小平明确提出“科学技术是第一生产力”，丰富和发展了马克思主义生产力理论。故本题选A。","__sub":"中特","_shard":"qk-zhengzhi-01"},{"id":"zz-30092","module":"zhengzhi","prompt":"“和平与发展是当代世界的主题”这一判断是在哪次大会提出的","options":["党的十四大","党的十二大","党的十一届三中全会","党的十三大"],"answer":1,"explanation":"邓小平在20世纪80年代作出和平与发展是当代世界两大主题的判断，党的十二大报告对此作出系统阐述，成为对外开放政策的重要依据。故本题选B。","__sub":"中特","_shard":"qk-zhengzhi-01"},{"id":"zz-30093","module":"zhengzhi","prompt":"“一国两制”构想最初是为解决什么问题提出的","options":["边界争端问题","香港问题","台湾问题","澳门问题"],"answer":2,"explanation":"“一国两制”最初是针对台湾问题提出的，首先运用于解决香港、澳门问题，核心是一个中国前提下两种制度并存。故本题选C。","__sub":"中特","_shard":"qk-zhengzhi-01"},{"id":"zz-30094","module":"zhengzhi","prompt":"“发展才是硬道理”这一论断出自","options":["邓小平南方谈话","《邓小平文选》第一卷","党的十一届三中全会报告","十五大报告"],"answer":0,"explanation":"1992年邓小平在南方谈话中提出“发展才是硬道理”，强调抓住机遇加快发展。故本题选A。","__sub":"中特","_shard":"qk-zhengzhi-01"},{"id":"zz-30095","module":"zhengzhi","prompt":"“三个代表”重要思想回答的核心问题是","options":["什么是现代化、怎样实现现代化","建设什么样的党、怎样建设党","实现什么样的发展、怎样发展","什么是社会主义、怎样建设社会主义"],"answer":1,"explanation":"“三个代表”重要思想在邓小平理论基础上，进一步回答了建设什么样的党、怎样建设党的问题。故本题选B。","__sub":"中特","_shard":"qk-zhengzhi-01"},{"id":"zz-30096","module":"zhengzhi","prompt":"“三个代表”重要思想的内容包括：代表中国先进生产力的发展要求、代表中国先进文化的前进方向，以及","options":["代表少数先进分子的利益","代表中国最广大人民的根本利益","代表全体公民的所有利益","代表国际社会的普遍利益"],"answer":1,"explanation":"“三个代表”即始终代表中国先进生产力的发展要求、中国先进文化的前进方向、中国最广大人民的根本利益。故本题选B。","__sub":"中特","_shard":"qk-zhengzhi-01"},{"id":"zz-30097","module":"zhengzhi","prompt":"科学发展观的第一要义是","options":["以人为本","全面协调可持续","发展","统筹兼顾"],"answer":2,"explanation":"科学发展观：第一要义是发展，核心立场是以人为本，基本要求是全面协调可持续，根本方法是统筹兼顾。故本题选C。","__sub":"中特","_shard":"qk-zhengzhi-01"},{"id":"zz-30098","module":"zhengzhi","prompt":"科学发展观的核心理念是","options":["节能减排","以人为本","又好又快","改革开放"],"answer":1,"explanation":"以人为本是科学发展观的核心立场，回答了发展为了谁、依靠谁、发展成果由谁享有这个根本问题。故本题选B。","__sub":"中特","_shard":"qk-zhengzhi-01"},{"id":"zz-30099","module":"zhengzhi","prompt":"把邓小平理论确立为党的指导思想并写入党章的是","options":["党的十六大","党的十四大","党的十五大","党的十七大"],"answer":2,"explanation":"1997年党的十五大将邓小平理论写入党章并确立为党的指导思想；十六大把“三个代表”重要思想写入党章。故本题选C。","__sub":"中特","_shard":"qk-zhengzhi-01"},{"id":"zz-30100","module":"zhengzhi","prompt":"党的十四大最重要的历史性决策是","options":["确立建立社会主义市场经济体制的改革目标","把科学发展观写入党章","提出全面建设小康社会","提出“三个代表”重要思想"],"answer":0,"explanation":"1992年党的十四大明确提出我国经济体制改革的目标是建立社会主义市场经济体制，这是社会主义发展史上的重大创举。故本题选A。","__sub":"中特","_shard":"qk-zhengzhi-01"},{"id":"zz-30101","module":"zhengzhi","prompt":"“解放思想、实事求是”思想路线重新确立的会议是","options":["党的十二大","党的十一届六中全会","党的十一届三中全会","党的十三大"],"answer":2,"explanation":"1978年党的十一届三中全会重新确立了解放思想、实事求是的思想路线，作出把党和国家工作中心转移到经济建设上来、实行改革开放的历史性决策。故本题选C。","__sub":"中特","_shard":"qk-zhengzhi-01"},{"id":"zz-30102","module":"zhengzhi","prompt":"“三个有利于”标准是指是否有利于发展社会主义社会的生产力，是否有利于增强社会主义国家的综合国力，以及","options":["是否有利于减少财政赤字","是否有利于控制人口数量","是否有利于提高人民的生活水平","是否有利于扩大公有制规模"],"answer":2,"explanation":"1992年南方谈话提出判断改革得失成败的“三个有利于”标准，核心是把生产力标准和人民利益标准统一起来。故本题选C。","__sub":"中特","_shard":"qk-zhengzhi-01"},{"id":"zz-30103","module":"zhengzhi","prompt":"社会主义初级阶段的含义包括两层：一是我国已经是社会主义社会，二是","options":["我国即将进入共产主义社会","我国的社会主义还处在初级阶段","我国处于新民主主义社会","我国已经是发达的社会主义"],"answer":1,"explanation":"社会主义初级阶段不是泛指任何国家进入社会主义都要经历的阶段，而是特指我国在生产力落后、商品经济不发达条件下建设社会主义必然要经历的特定阶段。故本题选B。","__sub":"中特","_shard":"qk-zhengzhi-01"},{"id":"zz-30104","module":"zhengzhi","prompt":"“贫穷不是社会主义”这一命题的主要含义是","options":["社会主义可以容忍两极分化","物质鼓励高于精神鼓励","平均主义就是社会主义","社会主义的根本任务是解放和发展生产力"],"answer":3,"explanation":"邓小平强调社会主义要消灭贫穷，根本任务是解放和发展生产力，贫穷不是社会主义的本质特征。故本题选D。","__sub":"中特","_shard":"qk-zhengzhi-01"},{"id":"zz-30105","module":"zhengzhi","prompt":"“摸着石头过河”这一改革方法论强调","options":["在实践中探索、试验、总结经验、逐步推进","完全依赖既定理论","暂停改革步伐","照搬外国模式"],"answer":0,"explanation":"“摸着石头过河”强调改革是前无古人的事业，要在实践中大胆试验、及时总结、稳步推进，体现了实践第一的观点。故本题选A。","__sub":"中特","_shard":"qk-zhengzhi-01"},{"id":"zz-30106","module":"zhengzhi","prompt":"“先富带后富”政策的理论依据是","options":["允许两极分化长期存在","共同富裕是一个有先有后、逐步实现的历史过程","同步富裕才能体现优越性","平均主义分配原则"],"answer":1,"explanation":"允许和鼓励一部分地区、一部分人先富起来，带动越来越多的人走向富裕，最终达到共同富裕，这是实现共同富裕的必由之路。故本题选B。","__sub":"中特","_shard":"qk-zhengzhi-01"},{"id":"zz-30107","module":"zhengzhi","prompt":"四项基本原则中居于核心地位的是","options":["坚持马列主义毛泽东思想","坚持中国共产党的领导","坚持社会主义道路","坚持人民民主专政"],"answer":1,"explanation":"四项基本原则是立国之本，其中坚持党的领导是核心；离开党的领导，其他三项原则都无从落实。故本题选B。","__sub":"中特","_shard":"qk-zhengzhi-01"},{"id":"zz-30108","module":"zhengzhi","prompt":"党的十六大提出的奋斗目标是","options":["建成社会主义市场经济体制","实现共同富裕","全面建设小康社会","基本实现现代化"],"answer":2,"explanation":"2002年党的十六大提出在本世纪头二十年全面建设小康社会的目标。故本题选C。","__sub":"中特","_shard":"qk-zhengzhi-01"},{"id":"zz-30109","module":"zhengzhi","prompt":"“政治文明”作为社会主义现代化建设重要目标写入党的文件始于","options":["党的十五大","党的十六大","党的十八大","党的十七大"],"answer":1,"explanation":"党的十六大提出建设社会主义政治文明，形成物质文明、政治文明、精神文明协调发展的布局。故本题选B。","__sub":"中特","_shard":"qk-zhengzhi-01"},{"id":"zz-30110","module":"zhengzhi","prompt":"邓小平强调“中国的事情能不能办好，从一定意义上说关键在人”，其哲学依据是","options":["认识决定实践","人的因素在实践活动中具有能动性","外因是变化的根据","意识可以直接改变物质"],"answer":1,"explanation":"人是实践活动最活跃的因素，人的素质、积极性直接影响实践成效，体现了实践主体能动性的原理；意识必须通过实践才能作用于物质。故本题选B。","__sub":"中特","_shard":"qk-zhengzhi-01"},{"id":"zz-30111","module":"zhengzhi","prompt":"习近平新时代中国特色社会主义思想的核心内容可以概括为","options":["“八个明确”“八个坚持”","“十个明确”“十四个坚持”“十三个方面成就”","“五个明确”“十个坚持”","“六个明确”“十二个坚持”"],"answer":1,"explanation":"党的十九大提出“八个明确”“十四个坚持”，党的十九届六中全会扩展为“十个明确”，并概括了“十三个方面成就”，共同构成这一思想的核心内容。故本题选B。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30112","module":"zhengzhi","prompt":"“六个必须坚持”中，排在首位的是","options":["必须坚持问题导向","必须坚持守正创新","必须坚持人民至上","必须坚持自信自立"],"answer":2,"explanation":"党的二十大报告提出把握“六个必须坚持”：坚持人民至上、自信自立、守正创新、问题导向、系统观念、胸怀天下，其中人民至上排在首位，是根本价值立场。故本题选C。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30113","module":"zhengzhi","prompt":"“两个结合”是指把马克思主义基本原理同中国具体实际相结合、同","options":["现代科学技术相结合","中华优秀传统文化相结合","市场经济体制相结合","世界先进文明相结合"],"answer":1,"explanation":"“两个结合”是我们党推进理论创新的根本途径，第二个结合是又一次思想解放，表明党的历史自信、文化自信达到新高度。故本题选B。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30114","module":"zhengzhi","prompt":"中国式现代化的本质要求中，居于领导核心地位的是","options":["发展全过程人民民主","实现高质量发展","坚持中国共产党领导","丰富人民精神世界"],"answer":2,"explanation":"中国式现代化本质要求的第一条就是坚持中国共产党领导，党的领导直接关系中国式现代化的根本方向、前途命运和最终成败。故本题选C。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30115","module":"zhengzhi","prompt":"下列不属于中国式现代化五个方面中国特色的是","options":["全体人民同步富裕的现代化","物质文明和精神文明相协调的现代化","人与自然和谐共生的现代化","人口规模巨大的现代化"],"answer":0,"explanation":"中国式现代化五个特征：人口规模巨大、全体人民共同富裕、物质文明和精神文明相协调、人与自然和谐共生、走和平发展道路。共同富裕不是“同步富裕”，A项表述被偷换。故本题选A。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30116","module":"zhengzhi","prompt":"新时代我国社会主要矛盾是","options":["人民日益增长的物质文化需要同落后的社会生产之间的矛盾","城市与农村的矛盾","人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾","发展与安全的矛盾"],"answer":2,"explanation":"党的十九大作出新时代社会主要矛盾转化的重大政治论断，矛盾的主要方面在发展的不平衡不充分。故本题选C。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30117","module":"zhengzhi","prompt":"新时代我国社会主要矛盾的变化","options":["没有改变我们对我国社会主义所处历史阶段的判断","意味着我国基本国情发生根本改变","标志着我国已进入发达社会主义阶段","表明我国已经跨越社会主义初级阶段"],"answer":0,"explanation":"主要矛盾变化是关系全局的历史性变化，但我国仍处于并将长期处于社会主义初级阶段的基本国情没有变，我国是世界最大发展中国家判断没有变。故本题选A。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30118","module":"zhengzhi","prompt":"“十四个坚持”的基本方略中，居于统领地位的是","options":["坚持以人民为中心","坚持党对一切工作的领导","坚持全面深化改革","坚持新发展理念"],"answer":1,"explanation":"“十四个坚持”第一条是坚持党对一切工作的领导，党政军民学、东西南北中，党是领导一切的。故本题选B。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30119","module":"zhengzhi","prompt":"新发展理念的完整表述是","options":["创新、和谐、绿色、开放、共享","创新、协调、绿色、开放、共享","创新、协调、环保、开放、共享","科学、协调、绿色、开放、共赢"],"answer":1,"explanation":"创新是引领发展的第一动力，协调是持续健康发展的内在要求，绿色是永续发展的必要条件，开放是国家繁荣发展的必由之路，共享是中国特色社会主义的本质要求。故本题选B。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30120","module":"zhengzhi","prompt":"新发展理念中，解决发展不平衡问题的是","options":["绿色发展","开放发展","创新发展","协调发展"],"answer":3,"explanation":"协调发展注重解决发展不平衡问题，绿色发展注重解决人与自然和谐问题，开放发展注重解决内外联动问题，共享发展注重解决社会公平正义问题。故本题选D。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30121","module":"zhengzhi","prompt":"构建新发展格局的关键特征是","options":["完全依赖国内市场、关闭国际循环","沿海带动内陆的梯度发展","以国内大循环为主体、国内国际双循环相互促进","以国际大循环为主体"],"answer":2,"explanation":"构建以国内大循环为主体、国内国际双循环相互促进的新发展格局，是根据我国发展阶段、环境、条件变化作出的战略决策，绝不是封闭的国内循环。故本题选C。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30122","module":"zhengzhi","prompt":"新发展格局最本质的特征是","options":["压缩国内需求","扩大出口规模","实现高水平的自立自强","增加财政投入"],"answer":2,"explanation":"加快科技自立自强是畅通国内大循环、塑造国际竞争新优势的关键，新发展格局最本质的特征是实现高水平的自立自强。故本题选C。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30123","module":"zhengzhi","prompt":"新质生产力的特点是","options":["速度","密度","规模","创新"],"answer":3,"explanation":"新质生产力是创新起主导作用的先进生产力质态，特点是创新，关键在质优，本质是先进生产力。故本题选D。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30124","module":"zhengzhi","prompt":"新质生产力由技术革命性突破、生产要素创新性配置、产业深度转型升级而催生，其基本内涵是","options":["产业链条的空间延伸","贸易规模的持续扩大","资本、土地、劳动力数量的增加","劳动者、劳动资料、劳动对象及其优化组合的跃升"],"answer":3,"explanation":"新质生产力以劳动者、劳动资料、劳动对象及其优化组合的跃升为基本内涵，以全要素生产率大幅提升为核心标志。故本题选D。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30125","module":"zhengzhi","prompt":"发展新质生产力的方法论要求是","options":["各地一哄而上、搞一种模式","因地制宜，有选择地推动新产业、新模式、新动能发展","忽视传统产业、只抓新兴产业","先污染后治理"],"answer":1,"explanation":"习近平总书记强调发展新质生产力要坚持从实际出发，先立后破、因地制宜、分类指导，防止一哄而上、泡沫化。故本题选B。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30126","module":"zhengzhi","prompt":"全过程人民民主是","options":["仅指协商民主","仅指选举环节的民主","西方代议制民主的中国版本","全链条、全方位、全覆盖的民主，是最广泛、最真实、最管用的社会主义民主"],"answer":3,"explanation":"全过程人民民主涵盖民主选举、民主协商、民主决策、民主管理、民主监督各环节，实现了过程民主和成果民主、程序民主和实质民主的统一。故本题选D。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30127","module":"zhengzhi","prompt":"全面依法治国的根本遵循和行动指南是","options":["经济效率原则","西方法治理论","习近平法治思想","传统律学思想"],"answer":2,"explanation":"习近平法治思想是马克思主义法治理论中国化的最新成果，是全面依法治国的根本遵循和行动指南。故本题选C。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30128","module":"zhengzhi","prompt":"全面依法治国的最大优势和根本保证是","options":["律师参与","司法独立","坚持党的领导","判例指导"],"answer":2,"explanation":"党的领导是全面依法治国的最大优势和根本保证，必须把党的领导贯彻到全面依法治国全过程和各方面。故本题选C。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30129","module":"zhengzhi","prompt":"总体国家安全观的宗旨是","options":["以领土安全为宗旨","以军事安全为宗旨","以人民安全为宗旨","以经济安全为宗旨"],"answer":2,"explanation":"总体国家安全观要求以人民安全为宗旨、以政治安全为根本、以经济安全为基础、以军事科技文化社会安全为保障、以促进国际安全为依托。故本题选C。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30130","module":"zhengzhi","prompt":"在总体国家安全观中，作为国家安全的根本的是","options":["生态安全","文化安全","资源安全","政治安全"],"answer":3,"explanation":"政治安全是国家安全的根本，核心是政权安全和制度安全，最根本的是维护党的领导和执政地位、维护中国特色社会主义制度。故本题选D。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30131","module":"zhengzhi","prompt":"“绿水青山就是金山银山”理念主要回答的问题是","options":["保护生态环境就是保护生产力、改善生态环境就是发展生产力","发展速度与经济规模的关系","城市与乡村的关系","对外开放与对内改革的关系"],"answer":0,"explanation":"“两山”理念阐明了经济发展与生态环境保护的关系，指出生态环境本身就是生产力，绿色发展是高质量发展的底色。故本题选A。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30132","module":"zhengzhi","prompt":"共同富裕是中国特色社会主义的本质要求，其实现路径的准确表述是","options":["通过同步富裕一步到位","通过高福利平均分配","通过限制高收入群体实现","在高质量发展中促进共同富裕，允许一部分人先富起来，先富带后富"],"answer":3,"explanation":"共同富裕是全体人民的富裕，不是少数人的富裕，也不是整齐划一的平均主义，要在高质量发展中分阶段促进。故本题选D。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30133","module":"zhengzhi","prompt":"“把权力关进制度的笼子里”针对的核心问题是","options":["规范和制约权力运行","取消监督机构","削弱政府职能","限制公民权利"],"answer":0,"explanation":"反腐败要坚持不敢腐、不能腐、不想腐一体推进，其中“不能腐”靠制度约束，把权力关进制度的笼子，让权力在阳光下运行。故本题选A。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30134","module":"zhengzhi","prompt":"新时代党的建设总要求明确，党的建设的主线是","options":["以反腐败为主线","以经济建设为主线","全面从严治党，以加强党的长期执政能力建设、先进性和纯洁性建设为主线","以机构改革为主线"],"answer":2,"explanation":"新时代党的建设总要求：坚持和加强党的全面领导，坚持党要管党、全面从严治党，以加强党的长期执政能力建设、先进性和纯洁性建设为主线。故本题选C。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30135","module":"zhengzhi","prompt":"党的自我革命是","options":["仅指纪律处分","西方政党制度的产物","跳出治乱兴衰历史周期率的第二个答案","第一个答案"],"answer":2,"explanation":"毛泽东在“窑洞对”中给出人民监督政府的第一个答案；经过百年奋斗特别是新时代实践，党给出了自我革命这第二个答案。故本题选C。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30136","module":"zhengzhi","prompt":"“一带一路”倡议的核心内涵是","options":["共商共建共享","单向援助","关税同盟","区域霸权"],"answer":0,"explanation":"共建“一带一路”秉持共商共建共享原则，追求发展、崇尚共赢、传递希望，是构建人类命运共同体的重要实践平台。故本题选A。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30137","module":"zhengzhi","prompt":"人类命运共同体的核心要义是","options":["建设持久和平、普遍安全、共同繁荣、开放包容、清洁美丽的世界","组建军事联盟","推行一种发展模式","建立单一世界政府"],"answer":0,"explanation":"人类命运共同体理念主张各国同舟共济、合作共赢，建设“五个世界”，不谋求模式输出和势力范围。故本题选A。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30138","module":"zhengzhi","prompt":"全球发展倡议、全球安全倡议、全球文明倡议共同的核心理念是","options":["争夺全球霸权","建立双边军事同盟","构建人类命运共同体","输出意识形态"],"answer":2,"explanation":"三大全球倡议分别聚焦发展、安全、文明三个维度，都是构建人类命运共同体理念的展开和实践路径。故本题选C。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30139","module":"zhengzhi","prompt":"“文化自信”的根基在于","options":["网络快餐文化","商业消费文化","中华优秀传统文化、革命文化和社会主义先进文化","外来流行文化"],"answer":2,"explanation":"文化自信来自对自身文化价值的充分肯定，其源头是中华优秀传统文化、革命文化和社会主义先进文化。故本题选C。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30140","module":"zhengzhi","prompt":"“第二个结合”被称为又一次的思想解放，其意义在于","options":["否定第一个结合","表明我们党对中国道路、理论、制度的认识达到了新高度","放弃理论创新","用传统文化替代马克思主义"],"answer":1,"explanation":"“第二个结合”让马克思主义成为中国的、中华优秀传统文化成为现代的，造就有机统一的新的文化生命体，表明党的历史自信、文化自信达到新高度。故本题选B。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30141","module":"zhengzhi","prompt":"新时代好干部标准的第一个要求是","options":["清正廉洁","信念坚定","敢于担当","勤政务实"],"answer":1,"explanation":"好干部标准是信念坚定、为民服务、勤政务实、敢于担当、清正廉洁，信念坚定摆在首位。故本题选B。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30142","module":"zhengzhi","prompt":"“国之大者”强调的是","options":["只关注眼前利益","胸怀大局、把握大势、着眼大事，自觉在大局下行动","只关注个人利益","只关注局部利益"],"answer":1,"explanation":"对“国之大者”心中有数，要求领导干部想问题、作决策多打大算盘、算大账，把部门工作放到党和国家事业大局中去定位。故本题选B。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30143","module":"zhengzhi","prompt":"把高质量发展作为全面建设社会主义现代化国家的首要任务，其判断依据是","options":["追求经济增速的最大化","我国社会主要矛盾变化和高质量发展阶段的内在要求","模仿发达国家路径","单纯扩大投资规模"],"answer":1,"explanation":"高质量发展是解决社会主要矛盾、建设现代化经济体系、构建新发展格局的必然要求，发展必须完整准确全面贯彻新发展理念。故本题选B。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30144","module":"zhengzhi","prompt":"“全过程人民民主”的重要制度载体不包括","options":["人民代表大会制度","基层群众自治制度","政治协商制度","三权分立制度"],"answer":3,"explanation":"人民代表大会制度、中国共产党领导的多党合作和政治协商制度、民族区域自治制度、基层群众自治制度是我国民主政治的制度载体；三权分立不是我国的制度安排。故本题选D。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30145","module":"zhengzhi","prompt":"我国的根本政治制度是","options":["民族区域自治制度","中国共产党领导的多党合作和政治协商制度","基层群众自治制度","人民代表大会制度"],"answer":3,"explanation":"人民代表大会制度是根本政治制度，其余三项是基本政治制度。故本题选D。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30146","module":"zhengzhi","prompt":"“四个全面”战略布局的最新表述是","options":["全面建设、全面协调、全面绿色、全面共享","全面改革、全面开放、全面法治、全面治党","全面建设社会主义现代化国家、全面深化改革、全面依法治国、全面从严治党","全面建成小康社会、全面深化改革、全面依法治国、全面从严治党"],"answer":2,"explanation":"随着第一个百年目标实现，“全面建成小康社会”调整为“全面建设社会主义现代化国家”，其余三个“全面”保持不变。故本题选C。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30147","module":"zhengzhi","prompt":"“五位一体”总体布局是指","options":["改革、发展、稳定、安全、民生","农业、工业、服务业、科技、教育","经济建设、政治建设、文化建设、社会建设、生态文明建设","东西南北中五大区域"],"answer":2,"explanation":"“五位一体”总体布局把生态文明建设纳入中国特色社会主义事业总体布局，是十八大以来的重大部署。故本题选C。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30148","module":"zhengzhi","prompt":"“四个自信”是指","options":["制度自信、文化自信、生态自信、社会自信","道路自信、理论自信、制度自信、文化自信","理论自信、道路自信、科技自信、教育自信","经济自信、政治自信、文化自信、军事自信"],"answer":1,"explanation":"“四个自信”与“四个意识”“两个维护”共同构成党的思想政治建设的重要内容。故本题选B。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30149","module":"zhengzhi","prompt":"“两个确立”的内容是","options":["确立改革开放和发展稳定","确立习近平同志党中央的核心、全党的核心地位，确立习近平新时代中国特色社会主义思想的指导地位","确立党的领导和依法治国","确立市场经济地位和计划经济地位"],"answer":1,"explanation":"“两个确立”是党的十九届六中全会作出的重大政治论断，是新时代最重要的政治成果。故本题选B。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30150","module":"zhengzhi","prompt":"“两个维护”是指","options":["坚决维护习近平总书记党中央的核心、全党的核心地位，坚决维护党中央权威和集中统一领导","维护个人权威和维护集体权威","维护地方利益和维护部门利益","维护市场秩序和维护社会秩序"],"answer":0,"explanation":"“两个维护”是党的最高政治原则和根本政治规矩。故本题选A。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30151","module":"zhengzhi","prompt":"碳达峰、碳中和的“双碳”目标是指","options":["2030年前实现碳达峰，2060年前实现碳中和","2025年前碳达峰，2050年前碳中和","2028年前碳达峰，2055年前碳中和","2035年前碳达峰，2060年前碳中和"],"answer":0,"explanation":"我国承诺二氧化碳排放力争于2030年前达到峰值，努力争取2060年前实现碳中和。故本题选A。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30152","module":"zhengzhi","prompt":"实现碳达峰碳中和目标的原则性要求是","options":["一刀切拉闸限电","全面停用化石能源","先立后破、稳妥推进","暂时搁置经济发展"],"answer":2,"explanation":"“双碳”目标要立足我国能源资源禀赋，坚持先立后破、通盘谋划，传统能源逐步退出必须建立在新能源安全可靠的替代基础上。故本题选C。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30153","module":"zhengzhi","prompt":"“人民对美好生活的向往就是我们的奋斗目标”体现的发展思想是","options":["以资本为中心的发展思想","以速度为中心的发展思想","以人民为中心的发展思想","以环境为中心的发展思想"],"answer":2,"explanation":"以人民为中心的发展思想回答了发展为了谁、依靠谁、成果由谁分享的根本问题，是新时代一切发展工作的出发点。故本题选C。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30154","module":"zhengzhi","prompt":"乡村振兴战略的总要求是","options":["经济繁荣、社会和谐、文化昌盛","生产发展、生活宽裕、乡风文明、村容整洁、管理民主","农业强、农村美、农民富","产业兴旺、生态宜居、乡风文明、治理有效、生活富裕"],"answer":3,"explanation":"十九大提出乡村振兴战略总要求是五句话二十字；B项是社会主义新农村建设的要求。故本题选D。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30155","module":"zhengzhi","prompt":"把解决好“三农”问题作为全党工作重中之重，其重点在于","options":["压缩耕地面积","推动农民全部进城","减少农业投入","巩固脱贫攻坚成果，全面推进乡村振兴"],"answer":3,"explanation":"民族要复兴，乡村必振兴。脱贫攻坚取得胜利后要全面推进乡村振兴，这是“三农”工作重心的历史性转移。故本题选D。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30156","module":"zhengzhi","prompt":"粮食安全的根本方针是","options":["扩大经济作物替代口粮","退耕还林减少种植","完全依赖进口","以我为主、立足国内、确保产能、适度进口、科技支撑"],"answer":3,"explanation":"国家粮食安全战略强调谷物基本自给、口粮绝对安全，把中国人的饭碗牢牢端在自己手中。故本题选D。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30157","module":"zhengzhi","prompt":"“藏粮于地、藏粮于技”战略的核心要义是","options":["保护耕地和依靠科技提高粮食产能","限制粮食消费","扩大粮食储备库存","增加粮食进口配额"],"answer":0,"explanation":"“藏粮于地”重点是守住耕地红线、建设高标准农田；“藏粮于技”重点是依靠科技创新提升单产和品质。故本题选A。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30158","module":"zhengzhi","prompt":"意识形态工作的根本任务是","options":["减少舆论引导","放任多元思潮自由竞争","取消主流阵地","建设具有强大凝聚力和引领力的社会主义意识形态"],"answer":3,"explanation":"意识形态工作是为国家立心、为民族立魂的工作，必须牢牢掌握意识形态工作领导权。故本题选D。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30159","module":"zhengzhi","prompt":"办好中国的事情，关键在党。党的领导最本质的特征体现为","options":["中国共产党领导是中国特色社会主义最本质的特征","党领导一切具体事务","党政不分","党包办社会事务"],"answer":0,"explanation":"党的领导是中国特色社会主义最本质的特征和最大制度优势，但要改进领导方式，做到党领导一切与依宪依法执政相统一。故本题选A。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30160","module":"zhengzhi","prompt":"中国式现代化与其他国家现代化的共同特征是","options":["遵循现代化的一般规律，如工业化、城镇化、信息化等","完全照搬西方模式","拒绝一切国际经验","照搬苏联模式"],"answer":0,"explanation":"中国式现代化既有各国现代化的共同特征，更有基于自己国情的中国特色，是走自己的路的现代化。故本题选A。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30161","module":"zhengzhi","prompt":"“全过程人民民主”中，人民当家作主的根本途径和最高实现形式是","options":["网络问政平台","政治协商会议","人民代表大会制度","基层村民选举"],"answer":2,"explanation":"人民代表大会制度是坚持党的领导、人民当家作主、依法治国有机统一的根本政治制度安排，是人民当家作主的重要途径和最高实现形式。故本题选C。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30162","module":"zhengzhi","prompt":"新时代党员教育的总抓手是","options":["强化组织处分","扩大党员规模","增加经济待遇","用党的创新理论武装全党"],"answer":3,"explanation":"思想建设是党的基础性建设，坚持以科学理论引领、用党的创新理论武装全党，是新时代党员教育的根本任务。故本题选D。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30163","module":"zhengzhi","prompt":"中国式现代化的战略支撑是","options":["外资、外贸、外汇","关税、补贴、信贷","教育、科技、人才","资源、人口、区位"],"answer":2,"explanation":"党的二十大首次将教育、科技、人才进行一体化部署，指出教育是根本、科技是关键、人才是基础，共同支撑中国式现代化建设。故本题选C。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30164","module":"zhengzhi","prompt":"深化科技体制改革的重点是","options":["限制企业创新","减少科研投入","强化国家战略科技力量，实现高水平科技自立自强","取消基础研究"],"answer":2,"explanation":"国家实验室、国家科研机构、高水平研究型大学、科技领军企业共同构成国家战略科技力量。故本题选C。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30165","module":"zhengzhi","prompt":"“人民城市人民建、人民城市为人民”体现的城市治理理念是","options":["以效率为中心","以资本为中心","以形象为中心","以人民为中心"],"answer":3,"explanation":"城市治理要坚持人民城市理念，把最好的资源留给人民，用最优的服务服务人民。故本题选D。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30166","module":"zhengzhi","prompt":"基层治理“枫桥经验”的核心理念是","options":["依靠群众、就地化解矛盾，小事不出村、大事不出镇","悬置矛盾不处理","用强制手段压服群众","矛盾上交省级机关"],"answer":0,"explanation":"新时代“枫桥经验”坚持党的群众路线，坚持和发展矛盾预防化解在基层、在源头。故本题选A。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30167","module":"zhengzhi","prompt":"铸牢中华民族共同体意识是新时代党的民族工作的","options":["副产品","主线","前提","补充"],"answer":1,"explanation":"以铸牢中华民族共同体意识为主线，推动各民族像石榴籽一样紧紧抱在一起，是新时代党的民族工作的鲜明特征。故本题选B。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30168","module":"zhengzhi","prompt":"党的宗教工作基本方针要求坚持我国宗教","options":["中国化方向","商业化方向","去管理化方向","西方化方向"],"answer":0,"explanation":"坚持我国宗教中国化方向，积极引导宗教与社会主义社会相适应。故本题选A。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30169","module":"zhengzhi","prompt":"党史学习教育的重点内容之一是“学史明理、学史增信、学史崇德”，还有一项是","options":["学史育人","学史悟思","学史力行","学史促干"],"answer":2,"explanation":"“学史明理、学史增信、学史崇德、学史力行”是党史学习教育的目标要求，落脚点在“力行”。故本题选C。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30170","module":"zhengzhi","prompt":"党的二十大的主题是","options":["发展生产力，实现现代化","全面建成小康社会，实现共同富裕","坚持改革开放，建设市场经济","高举中国特色社会主义伟大旗帜，全面贯彻习近平新时代中国特色社会主义思想，弘扬伟大建党精神，自信自强、守正创新，踔厉奋发、勇毅前行，为全面建设社会主义现代化国家、全面推进中华民族伟大复兴而团结奋斗"],"answer":3,"explanation":"二十大主题明确了新征程上举什么旗、走什么路、以什么样的精神状态、朝着什么样的目标继续前进。故本题选D。","__sub":"习思想","_shard":"qk-zhengzhi-01"},{"id":"zz-30171","module":"zhengzhi","prompt":"中国共产党第一次全国代表大会召开的时间是","options":["1920年8月","1923年6月","1921年7月","1922年7月"],"answer":2,"explanation":"1921年7月23日党的一大在上海召开，后转移到嘉兴南湖游船上闭幕，宣告中国共产党正式成立。故本题选C。","__sub":"党史","_shard":"qk-zhengzhi-01"},{"id":"zz-30172","module":"zhengzhi","prompt":"党的二大的最重要历史贡献是","options":["制定了党的最低纲领和最高纲领","提出社会主义市场经济","决定进行武装斗争","确立毛泽东思想为指导思想"],"answer":0,"explanation":"1922年党的二大第一次明确提出了反帝反封建的民主革命纲领，为中国革命指明了方向。故本题选A。","__sub":"党史","_shard":"qk-zhengzhi-01"},{"id":"zz-30173","module":"zhengzhi","prompt":"第一次国共合作正式形成的标志是","options":["南昌起义","秋收起义","共产党一大召开","国民党一大召开"],"answer":3,"explanation":"1924年1月国民党一大在广州召开，确立了联俄、联共、扶助农工三大政策，国共合作正式形成。故本题选D。","__sub":"党史","_shard":"qk-zhengzhi-01"},{"id":"zz-30174","module":"zhengzhi","prompt":"打响武装反抗国民党反动派第一枪的是","options":["平江起义","南昌起义","秋收起义","广州起义"],"answer":1,"explanation":"1927年8月1日南昌起义打响了武装反抗国民党反动派的第一枪，8月1日由此成为建军节。故本题选B。","__sub":"党史","_shard":"qk-zhengzhi-01"},{"id":"zz-30175","module":"zhengzhi","prompt":"创建中国第一个农村革命根据地的是","options":["鄂豫皖革命根据地","井冈山革命根据地","中央革命根据地","延安革命根据地"],"answer":1,"explanation":"秋收起义受挫后，毛泽东率部创建井冈山革命根据地，开辟了农村包围城市、武装夺取政权的道路。故本题选B。","__sub":"党史","_shard":"qk-zhengzhi-01"},{"id":"zz-30176","module":"zhengzhi","prompt":"红军长征途中，实现党的历史上生死攸关转折的会议是","options":["洛川会议","遵义会议","八七会议","瓦窑堡会议"],"answer":1,"explanation":"遵义会议在极端危急关头挽救了党、挽救了红军、挽救了中国革命，标志着党在政治上开始走向成熟。故本题选B。","__sub":"党史","_shard":"qk-zhengzhi-01"},{"id":"zz-30177","module":"zhengzhi","prompt":"抗日战争时期，中共中央所在地延安被称为","options":["工业重镇","革命圣地","文化孤岛","商业中心"],"answer":1,"explanation":"延安是中共中央1937年至1947年的所在地，是抗日战争和解放战争的指挥中枢与总后方。故本题选B。","__sub":"党史","_shard":"qk-zhengzhi-01"},{"id":"zz-30178","module":"zhengzhi","prompt":"延安整风运动最主要的任务是","options":["反对宗派主义以整顿党风","反对官僚主义以整顿政风","反对党八股以整顿文风","反对主观主义以整顿学风"],"answer":3,"explanation":"延安整风运动的内容是反对主观主义以整顿学风、反对宗派主义以整顿党风、反对党八股以整顿文风，其中反对主观主义是最主要的任务。故本题选D。","__sub":"党史","_shard":"qk-zhengzhi-01"},{"id":"zz-30179","module":"zhengzhi","prompt":"中国人民抗日战争胜利的根本原因是","options":["中国共产党发挥中流砥柱作用，实行全民族抗战","偶然的自然灾害","敌人后勤供应中断","外国军队的直接参战"],"answer":0,"explanation":"中国共产党坚持全面抗战路线，开辟敌后战场，成为全民族抗战的中流砥柱，这是抗战胜利的决定性因素。故本题选A。","__sub":"党史","_shard":"qk-zhengzhi-01"},{"id":"zz-30180","module":"zhengzhi","prompt":"解放战争时期战略决战阶段的三大战役是","options":["渡江、上海、广州战役","济南、太原、兰州战役","辽沈、淮海、平津战役","孟良崮、莱芜、豫东战役"],"answer":2,"explanation":"辽沈、淮海、平津三大战役基本消灭了国民党军队的主力，奠定了解放战争在全国胜利的基础。故本题选C。","__sub":"党史","_shard":"qk-zhengzhi-01"},{"id":"zz-30181","module":"zhengzhi","prompt":"党的七届二中全会讨论的重要主题是","options":["解放区的经济建设","土地改革的方法","党的工作重心由乡村转移到城市","抗日战争的策略"],"answer":2,"explanation":"1949年七届二中全会决定把党的工作重心由乡村转移到城市，并提出了“两个务必”。故本题选C。","__sub":"党史","_shard":"qk-zhengzhi-01"},{"id":"zz-30182","module":"zhengzhi","prompt":"第一部《中华人民共和国宪法》诞生于","options":["1954年","1975年","1956年","1949年"],"answer":0,"explanation":"1954年第一届全国人民代表大会第一次会议通过了《中华人民共和国宪法》，这是新中国第一部社会主义类型的宪法。故本题选A。","__sub":"党史","_shard":"qk-zhengzhi-01"},{"id":"zz-30183","module":"zhengzhi","prompt":"我国社会主义制度基本建立的标志是","options":["加入世界贸易组织","新中国的成立","改革开放的启动","社会主义改造基本完成"],"answer":3,"explanation":"1956年对农业、手工业、资本主义工商业的社会主义改造基本完成，确立了社会主义基本制度。故本题选D。","__sub":"党史","_shard":"qk-zhengzhi-01"},{"id":"zz-30184","module":"zhengzhi","prompt":"“文化大革命”结束后，重新确立马克思主义思想路线的会议是","options":["党的十一届三中全会","党的十二大","党的十一届六中全会","党的十三大"],"answer":0,"explanation":"十一届三中全会重新确立解放思想、实事求是的思想路线，开启了改革开放和社会主义现代化建设新时期。故本题选A。","__sub":"党史","_shard":"qk-zhengzhi-01"},{"id":"zz-30185","module":"zhengzhi","prompt":"作出《关于建国以来党的若干历史问题的决议》的会议是","options":["党的十九届六中全会","党的十一届六中全会","党的十一届三中全会","党的十二大"],"answer":1,"explanation":"1981年党的十一届六中全会通过该决议，科学评价了毛泽东同志的历史地位和毛泽东思想。故本题选B。","__sub":"党史","_shard":"qk-zhengzhi-01"},{"id":"zz-30186","module":"zhengzhi","prompt":"首次提出“建设有中国特色的社会主义”重大命题的是","options":["党的十三大","党的十二大","党的十五大","党的十四大"],"answer":1,"explanation":"1982年党的十二大开幕式上，邓小平提出“走自己的道路，建设有中国特色的社会主义”。故本题选B。","__sub":"党史","_shard":"qk-zhengzhi-01"},{"id":"zz-30187","module":"zhengzhi","prompt":"系统阐述社会主义初级阶段理论并制定“三步走”发展战略的大会是","options":["党的十三大","党的十五大","党的十四大","党的十二大"],"answer":0,"explanation":"1987年党的十三大系统阐述了社会主义初级阶段理论和党的基本路线，确定了“三步走”战略。故本题选A。","__sub":"党史","_shard":"qk-zhengzhi-01"},{"id":"zz-30188","module":"zhengzhi","prompt":"提出依法治国、建设社会主义法治国家基本方略的大会是","options":["党的十六大","党的十五大","党的十八大","党的十四大"],"answer":1,"explanation":"1997年党的十五大将依法治国确立为党领导人民治理国家的基本方略。故本题选B。","__sub":"党史","_shard":"qk-zhengzhi-01"},{"id":"zz-30189","module":"zhengzhi","prompt":"党的十八大将生态文明建设纳入总体布局，形成的新布局是","options":["“四位一体”","“三位一体”","“五位一体”","“六位一体”"],"answer":2,"explanation":"党的十八大把生态文明建设与经济、政治、文化、社会建设并列，形成“五位一体”总体布局。故本题选C。","__sub":"党史","_shard":"qk-zhengzhi-01"},{"id":"zz-30190","module":"zhengzhi","prompt":"党的十九届六中全会通过的第三个历史决议是","options":["《中共中央关于党的百年奋斗重大成就和历史经验的决议》","《关于若干历史问题的决议》","《中共中央关于全面深化改革若干重大问题的决定》","《关于建国以来党的若干历史问题的决议》"],"answer":0,"explanation":"2021年党的十九届六中全会通过党的第三个历史决议，概括了“十个坚持”的历史经验。故本题选A。","__sub":"党史","_shard":"qk-zhengzhi-01"},{"id":"zz-30191","module":"zhengzhi","prompt":"党的二十大提出，从现在起中国共产党的中心任务是","options":["全面建成小康社会","建立市场经济体制","团结带领全国各族人民全面建成社会主义现代化强国、实现第二个百年奋斗目标，以中国式现代化全面推进中华民族伟大复兴","打赢脱贫攻坚战"],"answer":2,"explanation":"二十大明确了新时代新征程党的中心任务，确立了分两步走的战略安排。故本题选C。","__sub":"党史","_shard":"qk-zhengzhi-01"},{"id":"zz-30192","module":"zhengzhi","prompt":"全面建成小康社会、实现第一个百年奋斗目标之后，到2035年的目标是","options":["实现人均GDP翻两番","完成乡村振兴","全面建成富强民主文明和谐美丽的社会主义现代化强国","基本实现社会主义现代化"],"answer":3,"explanation":"党的二十大战略安排：2035年基本实现社会主义现代化，到本世纪中叶建成社会主义现代化强国。故本题选D。","__sub":"党史","_shard":"qk-zhengzhi-01"},{"id":"zz-30193","module":"zhengzhi","prompt":"伟大建党精神的内涵包括坚持真理、坚守理想，践行初心、担当使命，不怕牺牲、英勇斗争，以及","options":["对党忠诚、不负人民","艰苦奋斗、自力更生","统一思想、统一行动","独立自主、自力更生"],"answer":0,"explanation":"伟大建党精神是中国共产党的精神之源，四句话三十二个字。故本题选A。","__sub":"党史","_shard":"qk-zhengzhi-01"},{"id":"zz-30194","module":"zhengzhi","prompt":"中国共产党人的初心和使命是","options":["为全人类谋福利","为政党谋执政地位","为中国人民谋幸福，为中华民族谋复兴","为无产阶级谋特权"],"answer":2,"explanation":"这个初心和使命是激励中国共产党人不断前进的根本动力。故本题选C。","__sub":"党史","_shard":"qk-zhengzhi-01"},{"id":"zz-30195","module":"zhengzhi","prompt":"脱贫攻坚战取得全面胜利的时间是","options":["2021年","2023年","2018年","2020年初"],"answer":0,"explanation":"2021年2月25日，全国脱贫攻坚总结表彰大会宣告我国脱贫攻坚战取得全面胜利，现行标准下农村贫困人口全部脱贫。故本题选A。","__sub":"党史","_shard":"qk-zhengzhi-01"},{"id":"zz-30196","module":"zhengzhi","prompt":"全面建成小康社会的庄严宣告出自","options":["庆祝建国70周年大会","党的二十大","庆祝中国共产党成立100周年大会","党的十九大"],"answer":2,"explanation":"2021年7月1日，习近平总书记在庆祝建党100周年大会上庄严宣告，我们实现了第一个百年奋斗目标，全面建成了小康社会。故本题选C。","__sub":"党史","_shard":"qk-zhengzhi-01"},{"id":"zz-30197","module":"zhengzhi","prompt":"中国共产党领导人民在革命时期形成的精神谱系中，孕育于长征途中的精神是","options":["抗美援朝精神","载人航天精神","红船精神","伟大长征精神"],"answer":3,"explanation":"长征精神的核心包括坚定信念、不怕牺牲、独立自主、顾全大局等，是伟大建党精神在长征中的展开。故本题选D。","__sub":"党史","_shard":"qk-zhengzhi-01"},{"id":"zz-30198","module":"zhengzhi","prompt":"“半条被子”故事反映的党与群众的关系是","options":["交换与雇佣","管理与被管理","同人民风雨同舟、血脉相通","命令与服从"],"answer":2,"explanation":"三名女红军把仅有的一条被子剪下一半留给老乡，“半条被子”见证了共产党人与人民群众同甘共苦的鱼水深情。故本题选C。","__sub":"党史","_shard":"qk-zhengzhi-01"},{"id":"zz-30199","module":"zhengzhi","prompt":"中国共产党能够始终走在时代前列的根本原因在于","options":["坚持马克思主义指导并不断推进理论创新，勇于自我革命","历史偶然机遇","党员数量庞大","外部势力支持"],"answer":0,"explanation":"党的先进性源于科学理论的指导和自我革命的勇气，这是党永葆生机活力的根本保证。故本题选A。","__sub":"党史","_shard":"qk-zhengzhi-01"},{"id":"zz-30200","module":"zhengzhi","prompt":"遵义会议后，全党逐渐认识到必须在实践中形成和维护坚强的领导核心，其历史经验表明","options":["集体领导与核心作用对立","领导核心可有可无","核心是自封的","确立和维护党的领导核心对党的事业成败至关重要"],"answer":3,"explanation":"历史反复证明，一个成熟的马克思主义政党必须有坚强的领导核心，这是党百年奋斗的重要历史经验。故本题选D。","__sub":"党史","_shard":"qk-zhengzhi-01"},{"id":"zz-30201","module":"zhengzhi","prompt":"中国共产党的最高理想和最终目标是","options":["实现民族复兴","建成小康社会","实现共同富裕","实现共产主义"],"answer":3,"explanation":"党章总纲明确：党的最高理想和最终目标是实现共产主义。共同富裕、民族复兴是现阶段奋斗目标。故本题选D。","__sub":"党章党规","_shard":"qk-zhengzhi-01"},{"id":"zz-30202","module":"zhengzhi","prompt":"党章规定，中国共产党是中国工人阶级的先锋队，同时是","options":["全体公民的先锋队","知识分子的先锋队","企业家的先锋队","中国人民和中华民族的先锋队"],"answer":3,"explanation":"党章对党的性质的表述是“两个先锋队”：中国工人阶级的先锋队，中国人民和中华民族的先锋队。故本题选D。","__sub":"党章党规","_shard":"qk-zhengzhi-01"},{"id":"zz-30203","module":"zhengzhi","prompt":"党的根本组织原则是","options":["分级负责制","首长负责制","集体负责制","民主集中制"],"answer":3,"explanation":"民主集中制是民主基础上的集中和集中指导下的民主相结合，是党的根本组织原则和领导制度。故本题选D。","__sub":"党章党规","_shard":"qk-zhengzhi-01"},{"id":"zz-30204","module":"zhengzhi","prompt":"申请入党的年龄要求是","options":["不设年龄限制","年满二十岁","年满十六岁","年满十八岁的中国工人、农民、军人、知识分子和其他社会阶层的先进分子"],"answer":3,"explanation":"党章规定，年满十八岁的中国先进分子，承认党的纲领和章程，愿意参加党的组织并积极工作、执行党的决议和按期交纳党费的，可以申请加入中国共产党。故本题选D。","__sub":"党章党规","_shard":"qk-zhengzhi-01"},{"id":"zz-30205","module":"zhengzhi","prompt":"入党申请人的预备期为","options":["两年","半年","三年","一年"],"answer":3,"explanation":"党章规定，预备党员的预备期为一年，预备期从支部大会通过其为预备党员之日算起。故本题选D。","__sub":"党章党规","_shard":"qk-zhengzhi-01"},{"id":"zz-30206","module":"zhengzhi","prompt":"党的纪律处分共有五种，按轻重排序正确的是","options":["警告、严重警告、撤销党内职务、留党察看、开除党籍","警告、罚款、降级、撤职、开除","警告、通报、降职、留党察看、开除党籍","批评、警告、记过、撤职、开除"],"answer":0,"explanation":"党章和《中国共产党纪律处分条例》规定的五种党纪处分，由轻到重依次为警告、严重警告、撤销党内职务、留党察看、开除党籍。故本题选A。","__sub":"党章党规","_shard":"qk-zhengzhi-01"},{"id":"zz-30207","module":"zhengzhi","prompt":"留党察看的最长期限是","options":["三年","二年","六个月","一年"],"answer":1,"explanation":"留党察看分为一年、二年两种，最长不超过二年。故本题选B。","__sub":"党章党规","_shard":"qk-zhengzhi-01"},{"id":"zz-30208","module":"zhengzhi","prompt":"党的纪律主要包括政治纪律、组织纪律、廉洁纪律、群众纪律、工作纪律和","options":["保密纪律","财经纪律","生活纪律","家庭纪律"],"answer":2,"explanation":"“六项纪律”中政治纪律是最重要、最根本、最关键的纪律。故本题选C。","__sub":"党章党规","_shard":"qk-zhengzhi-01"},{"id":"zz-30209","module":"zhengzhi","prompt":"“四个意识”是指","options":["政治意识、大局意识、核心意识、看齐意识","道路意识、理论意识、制度意识、文化意识","经济意识、政治意识、文化意识、社会意识","改革意识、发展意识、稳定意识、安全意识"],"answer":0,"explanation":"增强“四个意识”、坚定“四个自信”、做到“两个维护”是党的政治建设的核心要求。故本题选A。","__sub":"党章党规","_shard":"qk-zhengzhi-01"},{"id":"zz-30210","module":"zhengzhi","prompt":"党的基层委员会每届任期一般为","options":["三年","四年","五年","六年"],"answer":2,"explanation":"根据党章和相关规定，党的基层委员会每届任期一般为五年。故本题选C。","__sub":"党章党规","_shard":"qk-zhengzhi-01"},{"id":"zz-30211","module":"zhengzhi","prompt":"党的中央委员会每届任期是","options":["三年","五年","四年","十年"],"answer":1,"explanation":"党的中央委员会每届任期五年，全国代表大会每五年举行一次。故本题选B。","__sub":"党章党规","_shard":"qk-zhengzhi-01"},{"id":"zz-30212","module":"zhengzhi","prompt":"党内最高的领导机关是","options":["中央军事委员会","中央书记处","党的全国代表大会和它所产生的中央委员会","中央政治局"],"answer":2,"explanation":"党章规定，党的最高领导机关是党的全国代表大会和它所产生的中央委员会。故本题选C。","__sub":"党章党规","_shard":"qk-zhengzhi-01"},{"id":"zz-30213","module":"zhengzhi","prompt":"《中国共产党廉洁自律准则》对党员和领导干部廉洁自律提出的总要求是","options":["只讲纪律、不讲道德","只讲工作、不讲生活","只讲奉献、不讲索取","公私分明、崇廉拒腐、尚俭戒奢、吃苦在前"],"answer":3,"explanation":"《准则》坚持正面倡导，要求党员正确处理公与私、廉与腐、俭与奢、苦与乐的关系。故本题选D。","__sub":"党章党规","_shard":"qk-zhengzhi-01"},{"id":"zz-30214","module":"zhengzhi","prompt":"全面从严治党首先要解决的问题是","options":["作风问题","效率问题","经济问题","政治问题"],"answer":3,"explanation":"政治纪律和政治规矩是最紧要的，全面从严治党首先要把党的政治建设摆在首位。故本题选D。","__sub":"党章党规","_shard":"qk-zhengzhi-01"},{"id":"zz-30215","module":"zhengzhi","prompt":"十九大党章修正案明确，党的建设的总体布局是","options":["纪律建设为统领","思想建设为统领","以党的政治建设为统领，全面推进党的政治建设、思想建设、组织建设、作风建设、纪律建设，把制度建设贯穿其中，深入推进反腐败斗争","组织建设为统领"],"answer":2,"explanation":"新时代党的建设布局以政治建设为统领，这是十九大党章修改的重要内容。故本题选C。","__sub":"党章党规","_shard":"qk-zhengzhi-01"},{"id":"zz-30216","module":"zhengzhi","prompt":"党支部担负的职责是","options":["直接教育党员、管理党员、监督党员和组织群众、宣传群众、凝聚群众、服务群众","只开会议","只收党费","只管发展党员"],"answer":0,"explanation":"《中国共产党支部工作条例》明确党支部七项基本职责，把党支部建设成为坚强战斗堡垒。故本题选A。","__sub":"党章党规","_shard":"qk-zhengzhi-01"},{"id":"zz-30217","module":"zhengzhi","prompt":"党的干部路线是","options":["论资排辈","以票取人","德才兼备、以德为先","唯才是举"],"answer":2,"explanation":"坚持德才兼备、以德为先的用人标准，突出政治标准，是新时代好干部选拔的根本导向。故本题选C。","__sub":"党章党规","_shard":"qk-zhengzhi-01"},{"id":"zz-30218","module":"zhengzhi","prompt":"党的各级领导干部必须具备的基本条件中，首位要求是","options":["具有履行职责所需要的马克思列宁主义、毛泽东思想、邓小平理论等的理论水平","群众基础好","年富力强","学历较高"],"answer":0,"explanation":"党章对干部基本条件的第一条即理论素养要求，强调用党的创新理论指导工作。故本题选A。","__sub":"党章党规","_shard":"qk-zhengzhi-01"},{"id":"zz-30219","module":"zhengzhi","prompt":"党内监督的专门机关（机构）是","options":["政府监察部门以外的独立机构","人民代表大会","政协监督机构","党的纪律检查委员会"],"answer":3,"explanation":"党的中央和地方各级纪律检查委员会是党内监督专责机关，负责监督执纪问责。故本题选D。","__sub":"党章党规","_shard":"qk-zhengzhi-01"},{"id":"zz-30220","module":"zhengzhi","prompt":"巡视制度的监督重点对象是","options":["党组织领导班子及其成员特别是主要负责人","党外群众","离退休干部","普通党员"],"answer":0,"explanation":"巡视是党内监督的战略性制度安排，重点监督领导班子特别是“一把手”。故本题选A。","__sub":"党章党规","_shard":"qk-zhengzhi-01"},{"id":"zz-30221","module":"zhengzhi","prompt":"《中国共产党问责条例》规定，问责对象的重点是","options":["社会组织","群众代表","普通党员","党组织和党的领导干部，特别是主要负责人"],"answer":3,"explanation":"问责坚持有权必有责、有责要担当、失责必追究，突出对主要领导责任的追究。故本题选D。","__sub":"党章党规","_shard":"qk-zhengzhi-01"},{"id":"zz-30222","module":"zhengzhi","prompt":"党员如果没有正当理由，连续多长时间不参加党的组织生活、或不交纳党费、或不做党所分配的工作，就被认为是自行脱党","options":["六个月","两年","一年","三个月"],"answer":0,"explanation":"党章第九条规定，连续六个月不参加组织生活、不交党费、不做党分配工作的，按自行脱党处理。故本题选A。","__sub":"党章党规","_shard":"qk-zhengzhi-01"},{"id":"zz-30223","module":"zhengzhi","prompt":"发展党员坚持的原则是","options":["速度优先","坚持把政治标准放在首位，坚持个别吸收","指标摊派","批量发展"],"answer":1,"explanation":"发展党员坚持党章规定的标准，始终把政治标准放在首位，成熟一个发展一个。故本题选B。","__sub":"党章党规","_shard":"qk-zhengzhi-01"},{"id":"zz-30224","module":"zhengzhi","prompt":"“三会一课”制度中的“三会”是指","options":["支部党员大会、支部委员会会议、党小组会","支委会、常委会、全会","党员大会、党代会、委员会","代表会、座谈会、汇报会"],"answer":0,"explanation":"“三会一课”即定期召开支部党员大会、支部委员会会议、党小组会，按时上好党课。故本题选A。","__sub":"党章党规","_shard":"qk-zhengzhi-01"},{"id":"zz-30225","module":"zhengzhi","prompt":"主题党日活动一般依托的组织形式是","options":["以党小组为单位每季度一次","以党支部为单位每月相对固定一天开展","以党委为单位每年一次","以个人为单位随机开展"],"answer":1,"explanation":"主题党日是党支部组织生活的重要形式，一般每月开展一次，做到主题突出、内容充实。故本题选B。","__sub":"党章党规","_shard":"qk-zhengzhi-01"},{"id":"zz-30226","module":"zhengzhi","prompt":"党的二十届四中全会审议通过的重要文件是","options":["《关于全面深化改革若干重大问题的决定》","《关于党的百年奋斗重大成就和历史经验的决议》","《中共中央关于制定国民经济和社会发展第十五个五年规划的建议》","《关于全面推进依法治国若干重大问题的决定》"],"answer":2,"explanation":"2025年10月召开的党的二十届四中全会审议通过了“十五五”规划建议，对今后五年经济社会发展作出战略部署。故本题选C。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30227","module":"zhengzhi","prompt":"“十五五”时期在现代化建设进程中的定位是","options":["脱贫攻坚的巩固时期","全面小康的收官时期","社会主义改造时期","基本实现社会主义现代化承上启下的关键时期"],"answer":3,"explanation":"四中全会判断，“十五五”时期是基本实现社会主义现代化夯实基础、全面发力的关键时期，到2035年要基本实现社会主义现代化。故本题选D。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30228","module":"zhengzhi","prompt":"党中央对“十五五”时期国内外环境的重大判断是","options":["风险已经全部消除","战略机遇期已经终结","环境完全稳定可测","战略机遇和风险挑战并存、不确定难预料因素增多"],"answer":3,"explanation":"全会强调我国发展环境面临深刻复杂变化，既看到机遇和有利条件，也正视风险挑战，增强确定性和可持续性。故本题选D。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30229","module":"zhengzhi","prompt":"“十五五”时期经济社会发展必须遵循的原则共有","options":["五项","八项","七项","六项"],"answer":3,"explanation":"六项原则：坚持党的全面领导、坚持人民至上、坚持高质量发展、坚持全面深化改革、坚持有效市场和有为政府相结合、坚持统筹发展和安全。故本题选D。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30230","module":"zhengzhi","prompt":"下列不属于“十五五”时期经济社会发展六项原则的是","options":["坚持党的全面领导","坚持数量扩张优先","坚持人民至上","坚持统筹发展和安全"],"answer":1,"explanation":"六项原则中不含“数量扩张优先”，高质量发展才是明确原则，数量扩张恰恰是要摒弃的旧路。故本题选B。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30231","module":"zhengzhi","prompt":"“十五五”时期经济社会发展的主题是","options":["以招商引资为主题","以推动高质量发展为主题","以扩大投资为主题","以消费补贴为主题"],"answer":1,"explanation":"必须坚持以经济建设为中心，以推动高质量发展为主题，以改革创新为根本动力。故本题选B。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30232","module":"zhengzhi","prompt":"“十五五”时期经济社会发展的根本目的是","options":["扩大财政盈余","满足人民日益增长的美好生活需要","增加出口规模","提升国际排名"],"answer":1,"explanation":"发展的根本目的是增进人民福祉，要让现代化建设成果更多更公平惠及全体人民。故本题选B。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30233","module":"zhengzhi","prompt":"下列属于“十五五”时期经济社会发展主要目标的是","options":["人均GDP超过发达国家","高质量发展取得显著成效","全面建成小康社会","完成脱贫攻坚任务"],"answer":1,"explanation":"主要目标包括：高质量发展取得显著成效、科技自立自强水平大幅提高、进一步全面深化改革取得新突破、社会文明程度明显提升、人民生活品质不断提高、美丽中国建设取得新的重大进展、国家安全屏障更加巩固。故本题选B。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30234","module":"zhengzhi","prompt":"到2035年我国经济发展的远景目标之一是","options":["人均国内生产总值达到中等发达国家水平","人均GDP达到世界第一","人均GDP超越所有发达国家","人均GDP翻三番"],"answer":0,"explanation":"2035年远景目标包括经济实力、科技实力大幅跃升，人均国内生产总值达到中等发达国家水平，基本实现社会主义现代化。故本题选A。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30235","module":"zhengzhi","prompt":"全会提出，“十五五”时期建设现代化产业体系要坚持的方向是","options":["智能化、绿色化、融合化","全面虚拟化","单一化、集中化、快速化","外包化、代工化、低端化"],"answer":0,"explanation":"坚持智能化、绿色化、融合化方向，建设现代化产业体系，巩固壮大实体经济根基，保持制造业合理比重。故本题选A。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30236","module":"zhengzhi","prompt":"“十五五”时期产业体系建设的重点是","options":["压缩制造业比重","大力发展虚拟经济","全面去工业化","巩固壮大实体经济根基"],"answer":3,"explanation":"实体经济是现代化产业体系的根基，必须保持制造业合理比重，大力发展先进制造业。故本题选D。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30237","module":"zhengzhi","prompt":"全会提出，“十五五”时期要加快","options":["全盘引进国外技术","技术代购模式","放弃基础研究","高水平科技自立自强，引领发展新质生产力"],"answer":3,"explanation":"加快高水平科技自立自强，加强基础研究和关键核心技术攻关，推动科技创新和产业创新深度融合。故本题选D。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30238","module":"zhengzhi","prompt":"建设强大国内市场的要求是","options":["抑制消费、扩大库存","冻结投资规模","把扩大内需作为战略基点，让内需成为经济发展的主动力","完全依赖外部市场"],"answer":2,"explanation":"全会强调坚持以国内大循环为主体，坚持惠民生和促消费、投资于物和投资于人紧密结合，增强内需主动力。故本题选C。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30239","module":"zhengzhi","prompt":"“十五五”规划建议强调投资于人，其含义是","options":["主要投向房地产","主要投向形象工程","把更多资源用于人力资本建设，促进人的全面发展和人民生活品质提高","只投物不投人"],"answer":2,"explanation":"“投资于物和投资于人紧密结合”是“十五五”规划建议的新提法，突出教育、医疗、育幼、养老等人力资本投入。故本题选C。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30240","module":"zhengzhi","prompt":"全会对区域协调发展的部署是","options":["放弃都市圈建设","优化区域经济布局，鼓励各地发挥比较优势，支持经济大省挑大梁","全面压缩东部发展","区域平均用力、千城一面"],"answer":1,"explanation":"因地制宜、各展所长，发挥京津冀、长三角、粤港澳等动力源作用，提升成渝双城经济圈能级，持续推进长江经济带和黄河流域发展。故本题选B。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30241","module":"zhengzhi","prompt":"全会对农业农村现代化的部署要求中，摆在全党工作重中之重位置的是","options":["压缩农业用地","扩大城镇规模","解决好“三农”问题","发展工业旅游"],"answer":2,"explanation":"坚持把解决好“三农”问题作为全党工作重中之重，加快农业农村现代化，扎实推进乡村全面振兴。故本题选C。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30242","module":"zhengzhi","prompt":"关于深化农村土地制度改革，“十五五”规划建议明确的政策方向是","options":["普遍收回农民承包地","稳定土地承包关系，有序推进第二轮土地承包到期后再延长三十年","冻结农业经营流转","全面私有化土地"],"answer":1,"explanation":"保持土地承包关系稳定并长久不变，给农民吃上长效“定心丸”，稳妥推进承包延包工作。故本题选B。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30243","module":"zhengzhi","prompt":"全会关于对外开放的部署是","options":["退出多边机制","关闭开放平台","扩大高水平对外开放，开创合作共赢新局面","收缩对外经贸"],"answer":2,"explanation":"稳步扩大制度型开放，高质量共建“一带一路”，维护多边贸易体制，拓展国际循环。故本题选C。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30244","module":"zhengzhi","prompt":"制度型开放与商品要素流动型开放相比，重点是","options":["增加展会数量","规则、规制、管理、标准等制度层面的对接","扩大口岸吞吐量","降低关税税率"],"answer":1,"explanation":"制度型开放强调主动对接国际高标准经贸规则，深化国内相关领域改革，营造市场化法治化国际化营商环境。故本题选B。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30245","module":"zhengzhi","prompt":"全会提出繁荣发展社会主义文化，强调激发","options":["外来文化替代活力","单一商业文化活力","复古保守文化活力","全民族文化创新创造活力"],"answer":3,"explanation":"推进文化自信自强，激发全民族文化创新创造活力，促进人的全面发展和社会全面进步。故本题选D。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30246","module":"zhengzhi","prompt":"全会对民生工作的部署强调","options":["先富群体优先","民生让位于增长","福利均等化一步到位","加大保障和改善民生力度，扎实推进全体人民共同富裕"],"answer":3,"explanation":"坚持尽力而为、量力而行，加强普惠性、基础性、兜底性民生建设，解决好人民群众急难愁盼问题。故本题选D。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30247","module":"zhengzhi","prompt":"“十五五”时期收入分配制度改革的方向是","options":["提高居民收入在国民收入分配中的比重，扩大中等收入群体","固定现有分配格局","限制劳动报酬增长","取消再分配调节"],"answer":0,"explanation":"完善初次分配、再分配、第三次分配协调配套的制度体系，促进机会公平。故本题选A。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30248","module":"zhengzhi","prompt":"全会关于国家安全的部署是","options":["统筹发展和安全，建设更高水平平安中国","关闭边境管控","安全与发展对立取舍","放松安全能力建设"],"answer":0,"explanation":"推进国家安全体系和能力现代化，防范化解重大风险，以新安全格局保障新发展格局。故本题选A。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30249","module":"zhengzhi","prompt":"全会对国防和军队现代化的要求是","options":["军备竞赛优先","暂停军队现代化","如期实现建军一百年奋斗目标，开创国防和军队现代化新局面","只发展进攻力量"],"answer":2,"explanation":"坚持党对军队的绝对领导，全面加强练兵备战，提高捍卫国家主权、安全、发展利益的战略能力。故本题选C。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30250","module":"zhengzhi","prompt":"全会强调坚持和加强党的全面领导，要求","options":["保持贯彻落实党中央决策部署的战略定力，凝聚动员全社会力量","党政脱钩","各部门自主决策、各自为政","弱化政治监督"],"answer":0,"explanation":"坚持党中央集中统一领导是做好经济工作的根本保证，也是五年规划治理经验的首要一条。故本题选A。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30251","module":"zhengzhi","prompt":"制定和实施五年规划体现的制度优势是","options":["有利于搞多党轮替","有利于地方割据","有利于集中力量办大事、保持事业连续性","有利于短期行为"],"answer":2,"explanation":"五年规划是我们党治国理政的重要经验，体现了中国特色社会主义制度集中力量办大事、一张蓝图绘到底的独特优势。故本题选C。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30252","module":"zhengzhi","prompt":"“十五五”规划建议中“全面深刻准确领会全会精神”三个维度的正确排序是","options":["全面、准确、深刻","深刻、全面、准确","准确、全面、深刻","全面、深刻、准确"],"answer":3,"explanation":"习近平总书记在专题研讨班上强调：全面，就是以全局视野把握整体部署；深刻，就是知其然更知其所以然；准确，就是精准把握政策界限。故本题选D。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30253","module":"zhengzhi","prompt":"现代化产业体系建设中，“因地制宜发展新质生产力”的方法论依据是","options":["矛盾普遍性排斥特殊性","矛盾具有特殊性，要具体问题具体分析","一切从主观愿望出发","照搬先进地区模式"],"answer":1,"explanation":"各地资源禀赋、产业基础不同，发展新质生产力必须从实际出发、分类指导，这正是矛盾特殊性原理的运用。故本题选B。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30254","module":"zhengzhi","prompt":"“有效市场和有为政府相结合”这一原则的哲学依据是","options":["否定二者联系","坚持两点论，把握对立面的统一","只讲政府作用","只讲市场作用"],"answer":1,"explanation":"市场与政府既对立又统一，有效市场与有为政府相结合体现了辩证思维，避免单向度思维。故本题选B。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30255","module":"zhengzhi","prompt":"“十五五”时期美丽中国建设的目标要求是","options":["美丽中国建设取得新的重大进展","环境治理全面完成","重回粗放增长","停止一切开发活动"],"answer":0,"explanation":"作为主要目标之一，要求加快经济社会发展全面绿色转型，建设美丽中国先行区。故本题选A。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30256","module":"zhengzhi","prompt":"全会提出加快构建高水平社会主义市场经济体制，其目的在于","options":["恢复计划经济","取消宏观调控","削弱公有制","增强高质量发展动力"],"answer":3,"explanation":"坚持和完善社会主义基本经济制度，充分发挥市场在资源配置中的决定性作用，更好发挥政府作用。故本题选D。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30257","module":"zhengzhi","prompt":"“十五五”时期科技自立自强的目标定位是","options":["科技成果束之高阁","科研投入逐步减少","科技自立自强水平大幅提高","完全依赖技术引进"],"answer":2,"explanation":"这是“十五五”主要目标之一，要求在加强基础研究、提高原始创新能力上持续用力。故本题选C。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30258","module":"zhengzhi","prompt":"统筹推进教育科技人才一体发展，其内在逻辑是","options":["三者相互独立、互不相关","教育让位于产业","教育培养人才、人才支撑科技、科技反哺教育，形成良性循环","人才主要靠引进"],"answer":2,"explanation":"教育、科技、人才是内在统一的有机整体，一体推进是建设现代化强国的基础性、战略性支撑。故本题选C。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30259","module":"zhengzhi","prompt":"“十五五”规划建议关于人口与养老的政策取向是","options":["完善发展养老事业和养老产业政策机制，大力发展银发经济","忽视人口结构变化","限制老年消费","取消养老服务"],"answer":0,"explanation":"应对人口老龄化要发展养老事业和产业，健全社会保障体系，开发银发经济新空间。故本题选A。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30260","module":"zhengzhi","prompt":"住房制度改革方面，“十五五”规划建议强调","options":["放弃城市更新","加快构建房地产发展新模式，建设好房子","重启粗放式房产扩张","取消保障性住房"],"answer":1,"explanation":"构建房地产发展新模式，加大保障性住房建设和供给，满足人民群众高品质住房需要。故本题选B。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30261","module":"zhengzhi","prompt":"医疗卫生方面的部署重点是","options":["削减公立医院","停建基层医疗","取消医保报销","深化医药卫生体制改革，健全全民医保体系和公共卫生体系"],"answer":3,"explanation":"坚持人民健康优先发展战略，推动优质医疗资源扩容下沉和区域均衡布局。故本题选D。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30262","module":"zhengzhi","prompt":"全会提出建设文化强国的重点是","options":["单一商业化运作","忽视主流价值","繁荣发展社会主义文化，提升国家文化软实力和中华文化影响力","文化进口替代"],"answer":2,"explanation":"坚持马克思主义在意识形态领域指导地位的根本制度，推进文化强国建设。故本题选C。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30263","module":"zhengzhi","prompt":"“十五五”规划建议中的“海洋强国”建设要求是","options":["海洋让位于陆地","经略海洋、向海图强","放弃海洋权益","只抓渔业生产"],"answer":1,"explanation":"推动海洋经济高质量发展，加强海洋权益维护，加快建设海洋强国。故本题选B。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30264","module":"zhengzhi","prompt":"“十五五”时期国家安全体系和能力现代化的重点是","options":["增强维护国家安全能力，加强重点领域安全能力建设","放松政治安全","取消应急体系","忽视粮食安全"],"answer":0,"explanation":"统筹外部安全和内部安全、传统安全和非传统安全，筑牢国家安全屏障。故本题选A。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30265","module":"zhengzhi","prompt":"贯彻四中全会精神的方法论要求中，“不能顾此失彼”针对的是","options":["只抓单项","碎片化执行","各自为政","全面领会，把各项部署作为整体把握"],"answer":3,"explanation":"全面，就是以全局视野领会全会精神，将各项部署作为一个整体来把握，防止畸轻畸重。故本题选D。","__sub":"四中全会·十五五","_shard":"qk-zhengzhi-01"},{"id":"zz-30266","module":"zhengzhi","prompt":"2026年中央一号文件聚焦的主题是","options":["深化农村改革、扎实推进乡村全面振兴","压缩粮食生产","扩大重化工业","发展城市房地产"],"answer":0,"explanation":"中央一号文件持续聚焦“三农”，把深化农村改革与乡村全面振兴作为主线，巩固脱贫成果、建设宜居宜业和美乡村。故本题选A。","__sub":"年度时政","_shard":"qk-zhengzhi-01"},{"id":"zz-30267","module":"zhengzhi","prompt":"“绿水青山就是金山银山”理念提出20周年纪念活动强调的核心要义是","options":["先污染后治理","生态优先、绿色发展，把生态优势转化为发展优势","以牺牲环境换增长","生态与发展对立"],"answer":1,"explanation":"“两山”理念提出于2005年8月，20年来已成为全党全社会的共识和行动，绿色发展是高质量发展的底色。故本题选B。","__sub":"年度时政","_shard":"qk-zhengzhi-01"},{"id":"zz-30268","module":"zhengzhi","prompt":"新质生产力“三要素”的准确表述是","options":["劳动力、土地、机器","人才、资本、政策","技术、资金、土地","劳动者、劳动资料、劳动对象"],"answer":3,"explanation":"新质生产力要求劳动者、劳动资料、劳动对象实现跃升并进行优化组合，以全要素生产率大幅提升为核心标志。故本题选D。","__sub":"年度时政","_shard":"qk-zhengzhi-01"},{"id":"zz-30269","module":"zhengzhi","prompt":"培育和发展新质生产力的产业布局要求是","options":["只发展传统产业","取消产业规划","改造提升传统产业、培育壮大新兴产业、布局建设未来产业","全部淘汰传统产业"],"answer":2,"explanation":"坚持传统产业转型升级与新兴产业培育并重，超前布局未来产业，形成接续有序的产业梯队。故本题选C。","__sub":"年度时政","_shard":"qk-zhengzhi-01"},{"id":"zz-30270","module":"zhengzhi","prompt":"全国统一大市场建设的主要目标是","options":["抬高交易成本","各省市设立贸易壁垒","恢复地方保护主义","破除地方保护和市场分割，畅通国内大循环"],"answer":3,"explanation":"建设全国统一大市场是构建新发展格局的基础支撑和内在要求，重在规则统一、公平竞争。故本题选D。","__sub":"年度时政","_shard":"qk-zhengzhi-01"},{"id":"zz-30271","module":"zhengzhi","prompt":"数据作为新型生产要素，其要素地位的确立意味着","options":["数据与土地、劳动力、资本、技术等共同参与分配和流通","数据不参与分配","数据完全由境外平台掌握","数据属于个人隐私不可用"],"answer":0,"explanation":"数据是数字经济时代的新型生产要素，要建立数据产权制度和流通交易规则，同时保护个人信息安全。故本题选A。","__sub":"年度时政","_shard":"qk-zhengzhi-01"},{"id":"zz-30272","module":"zhengzhi","prompt":"“东数西算”工程的战略意图是","options":["东部算力全部外迁境外","取消数据中心建设","优化算力资源配置，把东部数据运算需求引导到西部算力枢纽","西部只发展农业"],"answer":2,"explanation":"“东数西算”统筹全国算力布局，促进数据中心绿色发展，带动西部数字基础设施建设和产业升级。故本题选C。","__sub":"年度时政","_shard":"qk-zhengzhi-01"},{"id":"zz-30273","module":"zhengzhi","prompt":"低空经济被列为培育的新兴产业，其主要应用场景不包括","options":["应急救援巡查","城市主干道重型货运","无人机物流配送","低空旅游观光"],"answer":1,"explanation":"低空经济以无人机、通用航空为主要载体，典型场景有物流、文旅、巡查、农业植保等；城市主干道重型货运仍以地面运输为主。故本题选B。","__sub":"年度时政","_shard":"qk-zhengzhi-01"},{"id":"zz-30274","module":"zhengzhi","prompt":"人工智能赋能产业发展的正确导向是","options":["完全替代人类劳动","放任算法无序发展","推动人工智能与实体经济深度融合，发展智能产业和智能化应用","禁止AI在民生领域应用"],"answer":2,"explanation":"人工智能要赋能千行百业，同时加强安全治理，确保安全、可靠、可控。故本题选C。","__sub":"年度时政","_shard":"qk-zhengzhi-01"},{"id":"zz-30275","module":"zhengzhi","prompt":"“ DeepSeek”等国产大模型走红体现的产业趋势是","options":["算力完全短缺","基础研究停滞","核心技术全面依赖进口","我国人工智能创新能力显著提升，开源生态加速发展"],"answer":3,"explanation":"国产大模型以低成本高性能出圈，反映出我国在人工智能领域的创新活力和开源开放生态的进步。故本题选D。","__sub":"年度时政","_shard":"qk-zhengzhi-01"},{"id":"zz-30276","module":"zhengzhi","prompt":"“新 ”东亚“ 文明”对比不合适，下面关于文明交流互鉴的正确表述是","options":["文明因交流而多彩，文明因互鉴而丰富","文明冲突不可避免","一种文明应当取代其他文明","文明有高低优劣之分"],"answer":0,"explanation":"习近平总书记提出全球文明倡议，主张尊重世界文明多样性，坚持文明平等、互鉴、对话、包容。故本题选A。","__sub":"年度时政","_shard":"qk-zhengzhi-01"},{"id":"zz-30277","module":"zhengzhi","prompt":"共建“一带一路”进入高质量发展新阶段，其标志之一是","options":["债务陷阱输出","从谋篇布局的“大写意”转向精耕细作的“工笔画”","只搞贸易不搞合作","停止境外项目"],"answer":1,"explanation":"共建“一带一路”坚持高标准、可持续、惠民生目标，统筹标志性工程和“小而美”民生项目。故本题选B。","__sub":"年度时政","_shard":"qk-zhengzhi-01"},{"id":"zz-30278","module":"zhengzhi","prompt":"上合组织等多边机制中中国倡导的伙伴关系精神是","options":["排他性小圈子","阵营对抗","组建军事同盟","结伴而不结盟"],"answer":3,"explanation":"中国主张发展全球伙伴关系，走对话而不对抗、结伴而不结盟的国与国交往新路。故本题选D。","__sub":"年度时政","_shard":"qk-zhengzhi-01"},{"id":"zz-30279","module":"zhengzhi","prompt":"中国提出的正确义利观要求","options":["见利忘义","重利轻义","义利相兼、以义为先","义利对立"],"answer":2,"explanation":"正确义利观是我国对外政策的价值取向，特别是在同发展中国家合作中做到义利兼顾、弘义融利。故本题选C。","__sub":"年度时政","_shard":"qk-zhengzhi-01"},{"id":"zz-30280","module":"zhengzhi","prompt":"关于国家领土主权问题的正确立场是","options":["台湾地位未定","台湾是中国领土不可分割的一部分，两岸同属一个中国","两个中国","一中一台"],"answer":1,"explanation":"世界上只有一个中国，台湾自古以来就是中国领土不可分割的一部分，中国政府是唯一合法代表全中国的政府。故本题选B。","__sub":"年度时政","_shard":"qk-zhengzhi-01"},{"id":"zz-30281","module":"zhengzhi","prompt":"香港、澳门问题的制度安排是","options":["取消自治权限","一国两制、港人治港、澳人治澳、高度自治","实行西式三权分立","两地实行联邦制"],"answer":1,"explanation":"“一国两制”是解决港澳问题、保持港澳长期繁荣稳定的最佳制度安排，落实“爱国者治港”“爱国者治澳”原则。故本题选B。","__sub":"年度时政","_shard":"qk-zhengzhi-01"},{"id":"zz-30282","module":"zhengzhi","prompt":"香港国安法实施后，香港局势的变化说明","options":["法治基础削弱","国家安全得到维护，香港由乱到治走向由治及兴","香港繁荣终止","国际地位丧失"],"answer":1,"explanation":"香港国安法的实施堵塞了国家安全漏洞，推动香港实现由乱到治的重大转折，进入由治及兴的新阶段。故本题选B。","__sub":"年度时政","_shard":"qk-zhengzhi-01"},{"id":"zz-30283","module":"zhengzhi","prompt":"新时代解决台湾问题的总体方略是","options":["放弃国家统一目标","武力解决作为首选","贯彻新时代党解决台湾问题的总体方略，坚持和平统一、反对“台独”分裂","搁置争议永久现状"],"answer":2,"explanation":"坚持一个中国原则和“九二共识”，坚持以和平方式实现统一，同时决不承诺放弃使用武力，针对的是外部势力干涉和“台独”分裂。故本题选C。","__sub":"年度时政","_shard":"qk-zhengzhi-01"},{"id":"zz-30284","module":"zhengzhi","prompt":"关于两岸经济交流合作的正确表述是","options":["深化两岸融合发展，扩大台湾同胞的受益面和获得感","阻断人员往来","限制两岸贸易","歧视台胞权益"],"answer":0,"explanation":"两岸经济合作与融合发展符合两岸同胞共同利益，大陆持续出台惠台利民政策措施。故本题选A。","__sub":"年度时政","_shard":"qk-zhengzhi-01"},{"id":"zz-30285","module":"zhengzhi","prompt":"新时代爱国主义教育的对象重点是","options":["老年人","青少年","公务人员","企业家"],"answer":1,"explanation":"《新时代爱国主义教育实施纲要》强调爱国主义教育从青少年抓起，推动爱国主义精神代代相传。故本题选B。","__sub":"年度时政","_shard":"qk-zhengzhi-01"},{"id":"zz-30286","module":"zhengzhi","prompt":"社会主义核心价值观在社会层面的内容是","options":["富强、民主、文明、和谐","自由、平等、公正、法治","爱国、敬业、诚信、友善","和平、发展、合作、共赢"],"answer":1,"explanation":"三个层面：国家层面富强、民主、文明、和谐；社会层面自由、平等、公正、法治；个人层面爱国、敬业、诚信、友善。故本题选B。","__sub":"年度时政","_shard":"qk-zhengzhi-01"},{"id":"zz-30287","module":"zhengzhi","prompt":"“法治社会”建设的重点在于","options":["否定道德作用","仅靠重典治乱","弘扬社会主义法治精神，建设法治文化，使尊法学法守法用法蔚然成风","只重立法不重实施"],"answer":2,"explanation":"法治社会是构筑法治国家的基础，要坚持依法治国和以德治国相结合。故本题选C。","__sub":"年度时政","_shard":"qk-zhengzhi-01"},{"id":"zz-30288","module":"zhengzhi","prompt":"“以德治国”与“依法治国”的关系是","options":["德治替代法治","法治排斥德治","相互结合、相辅相成","相互对立"],"answer":2,"explanation":"坚持依法治国和以德治国相结合，法律是成文的道德，道德是内心的法律。故本题选C。","__sub":"年度时政","_shard":"qk-zhengzhi-01"},{"id":"zz-30289","module":"zhengzhi","prompt":"我国粮食总产量在2024年首次迈上的新台阶是","options":["1.4万亿斤","1.3万亿斤","1.2万亿斤","1.5万亿斤"],"answer":0,"explanation":"2024年我国粮食总产量首次突破1.4万亿斤，但供需紧平衡格局没有改变，粮食安全这根弦不能放松。故本题选A。","__sub":"年度时政","_shard":"qk-zhengzhi-01"},{"id":"zz-30290","module":"zhengzhi","prompt":"关于人口高质量发展的正确表述是","options":["完善生育支持政策体系，加快建设生育友好型社会","放任生育率下滑","忽视人口结构变化","取消托育服务"],"answer":0,"explanation":"应对少子化老龄化要健全覆盖全人群、全生命周期的人口服务体系，降低生育养育教育成本。故本题选A。","__sub":"年度时政","_shard":"qk-zhengzhi-01"},{"id":"zz-30291","module":"zhengzhi","prompt":"“双减”政策指向的教育改革方向是","options":["全面取消义务教育","减轻义务教育阶段学生作业负担和校外培训负担","提高应试强度","增加课后收费服务"],"answer":1,"explanation":"“双减”旨在回归育人本质，推进教育公平与素质教育。故本题选B。","__sub":"年度时政","_shard":"qk-zhengzhi-01"},{"id":"zz-30292","module":"zhengzhi","prompt":"关于高校毕业生就业工作的正确导向是","options":["取消校园招聘","限制新兴职业","只抓升学率","把高校毕业生就业摆在就业工作突出位置，拓宽市场化社会化就业渠道"],"answer":3,"explanation":"就业是最大的民生，高校毕业生等重点群体就业是稳就业工作的重中之重。故本题选D。","__sub":"年度时政","_shard":"qk-zhengzhi-01"},{"id":"zz-30293","module":"zhengzhi","prompt":"防范化解地方政府债务风险的正确做法是","options":["建立同高质量发展相适应的政府债务管理机制，化解存量、严控增量","债务违约放任不管","挪用民生资金还债","无限扩张隐性债务"],"answer":0,"explanation":"统筹发展与安全，严肃财经纪律，坚决遏制隐性债务增量，稳妥化解存量。故本题选A。","__sub":"年度时政","_shard":"qk-zhengzhi-01"},{"id":"zz-30294","module":"zhengzhi","prompt":"新时代推进共同富裕需要避免的认识误区是","options":["把共同富裕理解为整齐划一的平均主义","分阶段促进","鼓励勤劳创新致富","做大做好蛋糕"],"answer":0,"explanation":"共同富裕是全体人民的富裕，不是少数人的富裕，也不是整齐划一的平均主义，要靠共同奋斗。故本题选A。","__sub":"年度时政","_shard":"qk-zhengzhi-01"},{"id":"zz-30295","module":"zhengzhi","prompt":"“平安中国”建设中关于矛盾纠纷化解的正确机制是","options":["矛盾上交等待处理","悬置信访制度","坚持和发展新时代“枫桥经验”，把矛盾化解在基层、化解在萌芽状态","以罚代管"],"answer":2,"explanation":"完善社会矛盾纠纷多元预防调处化解综合机制，共建共治共享的社会治理格局不断健全。故本题选C。","__sub":"年度时政","_shard":"qk-zhengzhi-01"},{"id":"zz-30296","module":"zhengzhi","prompt":"网络安全工作的正确原则是","options":["没有网络安全就没有国家安全，坚持安全和发展同步推进","网络无序竞争","先发展后安全","安全与发展对立"],"answer":0,"explanation":"网络安全和信息化是一体之两翼、驱动之双轮，必须统一谋划、统一部署、统一推进。故本题选A。","__sub":"年度时政","_shard":"qk-zhengzhi-01"},{"id":"zz-30297","module":"zhengzhi","prompt":"关于反食品浪费的正确表述是","options":["浪费纯属个人自由","鼓励攀比性消费","厉行节约、反对浪费，制止“大胃王”等极端吃播行为","取消公勺公筷"],"answer":2,"explanation":"《反食品浪费法》确立厉行节约、反对浪费的法律原则，中消协倡议抵制极端吃播，倡导健康文明的消费文化。故本题选C。","__sub":"年度时政","_shard":"qk-zhengzhi-01"},{"id":"zz-30298","module":"zhengzhi","prompt":"建设体育强国的正确方向是","options":["体育让位于娱乐","深化体教融合、体卫融合，促进群众体育和竞技体育全面发展","取消群众体育","唯金牌论"],"answer":1,"explanation":"体育强国建设坚持人民至上，把竞技体育与全民健身、体育产业协同推进。故本题选B。","__sub":"年度时政","_shard":"qk-zhengzhi-01"},{"id":"zz-30299","module":"zhengzhi","prompt":"“深地”“深海”“深空”探测接连取得突破，体现的国家战略是","options":["科研投入收缩","放弃前沿探索","坚持创新驱动发展，抢占科技竞争制高点","技术引进依赖"],"answer":2,"explanation":"从“深海一号”大气田到深地钻探、深空探测，重大工程彰显高水平科技自立自强的战略成效。故本题选C。","__sub":"年度时政","_shard":"qk-zhengzhi-01"},{"id":"zz-30300","module":"zhengzhi","prompt":"面向2035年建成文化强国的目标，正确的路径是","options":["全面复古照搬古制","文化保守封闭","全盘西化","坚持创造性转化、创新性发展，推动中华优秀传统文化焕发时代活力"],"answer":3,"explanation":"对中华优秀传统文化要坚持“两创”，即创造性转化、创新性发展，构筑中国精神、中国价值、中国力量。故本题选D。","__sub":"年度时政","_shard":"qk-zhengzhi-01"}]);